                                                        {policy.isPaidOut ? 'PAID' : 'PENDING'}
                                                    </span>
                                                    <span className="text-xs text-gray-500 mt-1 font-medium">
                                                        Est. ${(policy.commission || 0).toLocaleString()}
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
