import { Role, User } from '../types';

interface RoleManagementProps {
    currentUser: User;
}

const RoleManagement: React.FC<RoleManagementProps> = ({ currentUser }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [users, setUsers] = useState(MOCK_TEAM);
    const [toastMessage, setToastMessage] = useState<string | null>(null);

    const handleRoleChange = (userId: string, newRole: Role) => {
        // Prevent user from changing their own role in the UI to prevent lock-out
        // In a real app, the backend would also validate this.
        if (currentUser.name === users.find(u => u.id === userId)?.name && newRole !== 'ADMIN') {
             alert("You cannot demote your own account from the admin panel.");
             return;
        }

        setUsers(users.map(u => u.id === userId ? { ...u, role: newRole } : u));

        // Show success feedback
        const userName = users.find(u => u.id === userId)?.name;
        const roleDisplay = newRole === 'ADMIN' ? 'Super Admin' : newRole;
        setToastMessage(`Updated ${userName}'s role to ${roleDisplay}`);
        setTimeout(() => setToastMessage(null), 3000);
    };

    const filteredUsers = users.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="animate-fade-in space-y-6 relative">
            {/* Success Toast */}
            {toastMessage && (
                <div className="fixed top-4 right-4 z-50 bg-slate-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 animate-fade-in">
                    <Check size={16} className="text-green-400" />
                    <span className="text-sm font-medium">{toastMessage}</span>
                </div>
            )}

            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Role Management</h2>
                    <p className="text-slate-500 text-sm">Manage user roles and permissions across your organization</p>
                </div>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                    <input 
                        type="text" 
                        placeholder="Search users..." 
                        className="pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500 bg-white"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
