        e.preventDefault();
        setIsLoading(true);
        setError('');

        setTimeout(() => {
            const normalizedEmail = email.toLowerCase();

            // 1. Check for persisted overrides (Saved in Settings)
            try {
                const savedUsers = JSON.parse(localStorage.getItem('arise_users_overrides') || '{}');
                if (savedUsers[normalizedEmail]) {
                    onLogin(savedUsers[normalizedEmail]);
                    return;
                }
            } catch (e) {
                console.error("Error reading saved user data", e);
            }

            // 2. Fallback to Mock Data
            // Allow login for old demo email too, just in case user remembers 'alex@arise.com'
            const user = MOCK_USERS.find(u => 
                u.email.toLowerCase() === normalizedEmail || 
                (normalizedEmail === 'alex@arise.com' && u.role === 'ADMIN') // backward compat hack for demo feel
            );

            if (user) {
                onLogin(user);
            } else {
                setError('Invalid email or password.');
                setIsLoading(false);
            }
        }, 800);
    };

    const handleSignUp = (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        if (!newName || !newEmail || !newPassword) {
            setError('Please fill in all fields');
            setIsLoading(false);
            return;
