const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<ViewState>('DASHBOARD');

  // Persistence: Clients
  const [clients, setClients] = useState<Client[]>(() => {
    try {
      const saved = localStorage.getItem('arise_clients_v3');
      return saved ? JSON.parse(saved) : MOCK_CLIENTS;
    } catch (e) {
      console.error("Error loading clients:", e);
      return MOCK_CLIENTS;
    }
  });

  // Persistence: Applications
  const [applications, setApplications] = useState<Application[]>(() => {
      try {
          const saved = localStorage.getItem('arise_applications_v1');
          return saved ? JSON.parse(saved) : MOCK_APPLICATIONS;
      } catch (e) {
          return MOCK_APPLICATIONS;
      }
  });

  // Save Clients to LocalStorage
  useEffect(() => {
    try {
      localStorage.setItem('arise_clients_v3', JSON.stringify(clients));
    } catch (e) {
      console.error("Error saving clients:", e);
    }
  }, [clients]);

  // Save Applications to LocalStorage
  useEffect(() => {
      localStorage.setItem('arise_applications_v1', JSON.stringify(applications));
  }, [applications]);

  // Derived User Profile for components that need it
  const userProfile: UserProfile = currentUser ? {
      name: currentUser.name,
      email: currentUser.email,
      phone: '(555) 123-4567',
      avatarUrl: currentUser.avatarUrl
  } : { name: '', email: '', phone: '' };

  // Filter clients based on logged-in user
  // Managers, Agency Owners, and Admins can see all. Agents/Recruits only see theirs.
  const visibleClients = currentUser 
      ? (['MANAGER', 'AGENCY_OWNER', 'ADMIN'].includes(currentUser.role) 
          ? clients 
          : clients.filter(client => client.agentId === currentUser.id))
      : [];

  const canViewManagement = currentUser && ['MANAGER', 'AGENCY_OWNER', 'ADMIN'].includes(currentUser.role);
  const isSuperAdmin = currentUser?.role === 'ADMIN';

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isCopilotOpen, setIsCopilotOpen] = useState(false);

  // Logic to handle Application Status Changes and Move to Book of Business
  const handleUpdateApplication = (updatedApp: Application) => {
      setApplications(prevApps => prevApps.map(app => {
          if (app.id !== updatedApp.id) return app;

          const isNowApprovedOrIssued = updatedApp.status === 'Approved' || updatedApp.status === 'Issued';
          const wasApprovedOrIssued = app.status === 'Approved' || app.status === 'Issued';

          // Scenario 1: Transitioning to Approved/Issued -> Create Policy if not exists
          if (isNowApprovedOrIssued && !wasApprovedOrIssued) {
             createPolicyFromApplication(updatedApp);
          }

          // Scenario 2: Transitioning to Issued -> Mark existing linked policy as Paid
          if (updatedApp.status === 'Issued' && app.status !== 'Issued') {
             markPolicyAsPaid(updatedApp.id);
          }

          return updatedApp;
      }));
  };

  const markPolicyAsPaid = (appId: string) => {
      setClients(prevClients => prevClients.map(client => ({
          ...client,
          policies: client.policies.map(p => {
              if (p.applicationId === appId) {
                  return { ...p, isPaidOut: true };
              }
              return p;
          })
      })));
  };

  const handleDeleteApplication = (appId: string) => {
      if (window.confirm("Are you sure you want to delete this application?")) {
          setApplications(prev => prev.filter(a => a.id !== appId));
      }
  };

  const createPolicyFromApplication = (app: Application) => {
      // Find the client associated with this app
      const clientIndex = clients.findIndex(c => c.id === app.clientId);
      if (clientIndex === -1) return;

      const client = clients[clientIndex];
      const todayStr = new Date().toISOString().split('T')[0];
      // Default Life Policy to a super long end date or 20 year term depending on guess, using 20 years default for simplicity
      const nextYearStr = new Date(new Date().setFullYear(new Date().getFullYear() + 20)).toISOString().split('T')[0];

      // Map Application Product string to PolicyType enum best guess
      let policyType = PolicyType.TERM;
      const productLower = app.product.toLowerCase();

      if (productLower.includes('iul') || productLower.includes('indexed')) policyType = PolicyType.IUL;
      else if (productLower.includes('whole')) policyType = PolicyType.WHOLE;
      else if (productLower.includes('annuity')) policyType = PolicyType.ANNUITY;
      else if (productLower.includes('final') || productLower.includes('expense') || productLower.includes('burial')) policyType = PolicyType.FINAL_EXPENSE;
      else if (productLower.includes('health')) policyType = PolicyType.HEALTH;

      const newPolicy: Policy = {
          id: `pol-${Date.now()}`,
          applicationId: app.id,
          type: policyType,
          productName: app.product,
          policyNumber: `GEN-${Math.floor(Math.random() * 1000000)}`,
          carrier: app.carrier,
          premium: app.premium, // Annual Premium
          coverageAmount: app.coverageAmount || 0,
          commission: app.premium * 0.9, // approx 90%
          startDate: todayStr,
          endDate: nextYearStr,
          status: PolicyStatus.ACTIVE,
          isPaidOut: app.status === 'Issued', // Auto-mark as paid if status is Issued
          documentUrl: app.documentUrl // Carry over the uploaded application file
      };

      // Update Client with new Policy and Pipeline Stage
      const updatedClient = {
          ...client,
          pipelineStage: PipelineStage.ISSUED, // Move pipeline stage to issued
          policies: [newPolicy, ...client.policies]
      };

      const newClients = [...clients];
      newClients[clientIndex] = updatedClient;
      setClients(newClients);
  };

  const handleLogin = (user: User) => {
      setCurrentUser(user);
      const managementRoles: Role[] = ['MANAGER', 'AGENCY_OWNER', 'ADMIN'];
      // Default to Super Admin dashboard if admin
      if (user.role === 'ADMIN') {
        setActiveView('PLATFORM_ADMIN');
      } else {
        setActiveView(managementRoles.includes(user.role) ? 'MANAGER_DASHBOARD' : 'DASHBOARD');
      }
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setSelectedClient(null);
