import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { ChatMessage } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize client securely - assuming env var is present
const ai = new GoogleGenAI({ apiKey: API_KEY });

const SYSTEM_INSTRUCTION = `You are "ARISE AI", the advanced intelligent core of the ARISE Financial Systems operating system.
You serve insurance agents and agency managers.

Your Capabilities:
1. **Sales Coaching**: Analyze pipeline stages and suggest next steps to move leads forward.
2. **Product Knowledge**: Explain complex IUL, Annuity, and Term Life concepts.
3. **Drafting**: Write professional emails, texts, and policy review letters.
4. **Data Analysis**: Interpret production numbers, persistency scores, and chargeback risks.
5. **Manager Support**: If the user is a manager, provide insights on team performance and overrides.

Tone: Professional, motivational, strategic, and concise.

Context Awareness:
- You have access to the screen context provided in the prompt.
- Refer to specific clients, policies, or team members by name if they appear in context.
- If asked about "Compliance", emphasize the importance of E&O and AML documentation.
`;

export const createChatSession = (): Chat => {
  return ai.chats.create({
    model: 'gemini-2.5-flash',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      thinkingConfig: { thinkingBudget: 0 }, 
    }
  });
};

export const sendMessageToGemini = async (
  chat: Chat, 
  message: string, 
  context?: string
): Promise<AsyncGenerator<GenerateContentResponse, void, unknown>> => {

  let fullMessage = message;
  if (context) {
    fullMessage = `[ARISE SYSTEM CONTEXT]\n${context}\n\n[USER REQUEST]\n${message}`;
  }

  try {
    const responseStream = await chat.sendMessageStream({ message: fullMessage });
    return responseStream;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const quickSummarize = async (text: string): Promise<string> => {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: `Summarize the following client notes or policy details into one concise paragraph for an insurance agent CRM:\n\n${text}`
        });
        return response.text || "Could not generate summary.";
    } catch (e) {
        console.error("Summary error", e);
        return "Error generating summary.";
    }
}

