                                                    </span>
                                                </td>
                                            </tr>
                                         )
                                    })}
                                </tbody>
                            </table>
                        </div>
                        <div className="p-4 border-t border-gray-100 bg-gray-50 rounded-b-xl flex justify-end shrink-0">
