interface HealthCondition {
    id: string;
    name: string;
    category: string;
    questions?: {
        id: string;
        text: string;
        type: 'BOOLEAN' | 'NUMBER';
    }[];
}

const US_STATES = [
    'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'DC', 'FL', 'GA', 
    'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 
