interface RoleplayScenario {
    id: string;
    title: string;
    description: string;
    difficulty: 'Easy' | 'Medium' | 'Hard';
    aiPersona: string;
    objective: string;
}

const SCENARIOS: RoleplayScenario[] = [
    {
        id: 'cold_call_fex',
        title: 'Cold Call: Final Expense',
        description: 'Prospect filled out a Facebook form for "State Regulated Life Insurance" but has forgotten about it.',
