                            >
                                Exit
                            </button>
                        </div>
                    </div>

                    {/* Chat Area */}
                    <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50">
                        {messages.map((msg) => (
                            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`flex max-w-[80%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-end gap-3`}>
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 shadow-sm ${msg.role === 'user' ? 'bg-indigo-600' : 'bg-white border border-gray-200'}`}>
                                        {msg.role === 'user' ? <User size={16} className="text-white" /> : <Bot size={16} className="text-slate-600" />}
                                    </div>
                                    <div className={`p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${
                                        msg.role === 'user' 
                                            ? 'bg-indigo-600 text-white rounded-br-none' 
                                            : 'bg-white text-slate-800 border border-gray-100 rounded-bl-none'
                                    }`}>
                                        {msg.text}
                                    </div>
                                </div>
                            </div>
                        ))}

                        {isThinking && (
                            <div className="flex justify-start animate-pulse">
                                <div className="flex flex-row items-center gap-2 bg-white p-3 rounded-2xl rounded-bl-none shadow-sm border border-gray-100">
                                    <div className="flex gap-1">
                                        <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
                                        <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
                                        <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {feedback && (
                            <div className="mx-auto max-w-2xl bg-white rounded-xl border border-yellow-200 shadow-lg overflow-hidden mt-8 animate-fade-in-up">
                                <div className="bg-yellow-50 p-4 border-b border-yellow-100 flex items-center gap-2">
                                    <Trophy className="text-yellow-600" size={20} />
                                    <h4 className="font-bold text-yellow-800">Call Review</h4>
                                </div>
                                <div className="p-6 text-slate-700 text-sm leading-relaxed whitespace-pre-wrap">
                                    {feedback}
                                </div>
                                <div className="p-4 bg-slate-50 border-t border-gray-100 flex justify-center">
                                    <button 
                                        onClick={() => startSession(selectedScenario)}
                                        className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700 transition-colors"
                                    >
                                        <RefreshCw size={16} /> Redial
                                    </button>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    {/* Input Area */}
                    {isSessionActive && !feedback && (
                        <div className="p-4 bg-white border-t border-gray-200 shrink-0">
                            <div className="relative max-w-4xl mx-auto">
                                <input
                                    type="text"
                                    value={inputText}
                                    onChange={(e) => setInputText(e.target.value)}
                                    onKeyDown={handleKeyDown}
                                    placeholder="Type your response..."
