                                            onChange={e => setInputs({...inputs, heightFt: parseInt(e.target.value) || 0})}
                                        />
                                        <input 
                                            type="number"
                                            placeholder="In"
                                            className={numInputClass}
                                            value={inputs.heightIn || ''}
                                            onChange={e => setInputs({...inputs, heightIn: parseInt(e.target.value) || 0})}
