                                    <input 
                                        type="number" 
                                        step="1000"
                                        className={`${numInputClass} pl-7 font-bold text-slate-800`}
                                        value={inputs.coverage || ''}
                                        placeholder="0"
                                        onChange={e => setInputs({...inputs, coverage: e.target.value === '' ? 0 : parseInt(e.target.value)})}
