                                                    <div key={q.id}>
                                                        <label className="block text-[10px] uppercase font-bold text-gray-500 mb-1">{q.text}</label>
                                                        {q.type === 'BOOLEAN' ? (
                                                            <div className="flex gap-2">
                                                                <button 
                                                                    onClick={() => updateConditionAnswer(sc.conditionId, q.id, true)}
