                    </button>
                    <div className="flex items-center bg-white px-2 py-1 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-md transition-colors text-slate-600">
                            <ChevronLeft size={20} />
