                        <span className="font-bold text-slate-800 w-40 text-center select-none">
                            {monthName}
                        </span>
                        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-md transition-colors text-slate-600">
                            <ChevronRight size={20} />
                        </button>
                    </div>

                    <button 
                        onClick={() => setIsAddModalOpen(true)}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium transition-colors shadow-sm"
