                        ))}
                    </div>

                    {/* Grid Cells */}
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr">
                        {calendarGrid.map((cell, index) => {
                            if (!cell) {
                                return <div key={`empty-${index}`} className="bg-gray-50/30 border-b border-r border-gray-100 last:border-r-0"></div>;
                            }

                            const dayEvents = events.filter(e => e.date === cell.dateStr);
                            const isToday = cell.dateStr === todayStr;

                            return (
                                <div key={cell.dateStr} className={`border-b border-r border-gray-100 p-2 relative flex flex-col gap-1 hover:bg-gray-50/30 transition-colors last:border-r-0 ${isToday ? 'bg-indigo-50/10' : ''}`}>
                                    <div className="flex justify-between items-start">
                                        <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${isToday ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-700'}`}>
                                            {cell.day}
                                        </span>
                                        {dayEvents.length > 0 && (
                                            <span className="text-[10px] text-gray-400 font-medium hidden sm:inline">{dayEvents.length} items</span>
                                        )}
                                    </div>

                                    <div className="flex-1 flex flex-col gap-1 overflow-y-auto mt-1 custom-scrollbar">
                                        {dayEvents.map(event => (
                                            <div 
                                                key={event.id} 
                                                className={`group px-2 py-1 text-[10px] rounded border-l-2 truncate font-medium cursor-pointer transition-all hover:opacity-100 opacity-90 relative
                                                ${event.type === 'Meeting' ? 'bg-indigo-50 text-indigo-700 border-indigo-500' : 
                                                  event.type === 'Call' ? 'bg-green-50 text-green-700 border-green-500' : 
                                                  event.type === 'Compliance' ? 'bg-red-50 text-red-700 border-red-500' :
                                                  'bg-gray-100 text-gray-700 border-gray-500'}`}
                                                title={event.title}
                                            >
                                                {event.time && event.time !== '00:00' ? <span className="opacity-75 mr-1">{event.time}</span> : ''}
                                                {event.title}

                                                <button 
                                                    onClick={(e) => handleDeleteEvent(event.id, e)}
                                                    className="absolute right-1 top-1/2 -translate-y-1/2 hidden group-hover:block p-0.5 bg-white/50 rounded hover:bg-white text-red-600"
                                                >
                                                    <Trash2 size={10} />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Sidebar: Upcoming & Alerts */}
                <div className="space-y-6 overflow-y-auto custom-scrollbar lg:h-auto">
                     <div className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm">
                        <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                            <Clock size={16} className="text-indigo-600" /> Upcoming
                        </h3>
                        <div className="space-y-3">
                            {upcomingEvents.length === 0 ? (
                                <p className="text-sm text-gray-400 italic">No upcoming events scheduled.</p>
                            ) : upcomingEvents.map(event => (
                                <div key={event.id} className={`border-l-4 pl-3 py-1 relative group ${event.type === 'Meeting' ? 'border-indigo-500' : event.type === 'Call' ? 'border-green-500' : 'border-gray-300'}`}>
                                    <div className="flex justify-between items-start">
                                        <p className="text-sm font-bold text-slate-800 line-clamp-1">{event.title}</p>
                                        <button 
                                            onClick={(e) => handleDeleteEvent(event.id, e)}
                                            className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 transition-opacity"
                                        >
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                    <div className="flex items-center gap-3 text-xs text-gray-500 mt-1">
                                        <span className="flex items-center gap-1 font-medium text-slate-600">
                                            {event.date === todayStr ? 'Today' : new Date(event.date).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}
                                        </span>
                                        <span className="flex items-center gap-1">
                                            {event.type === 'Meeting' ? <MapPin size={12} /> : event.type === 'Call' ? <CheckSquare size={12} /> : <AlertCircle size={12} />} 
                                            {event.type}
                                        </span>
                                    </div>
                                </div>
