            let feedbackText = '';
            for await (const chunk of stream) {
                if (chunk.text) feedbackText += chunk.text;
            }
            setFeedback(feedbackText);
        } catch (e) {
            console.error(e);
        } finally {
            setIsThinking(false);
        }
    };

