    const handleEditClick = (goal: Goal) => {
        setEditingId(goal.id);
        setEditValues({ current: goal.current, target: goal.target });
    };

    const handleSave = (id: string) => {
        const updatedGoals = allGoals[activePeriod].map((g) => 
            g.id === id ? { ...g, current: Number(editValues.current), target: Number(editValues.target) } : g
        );

        setAllGoals(prev => ({
            ...prev,
            [activePeriod]: updatedGoals
        }));
        setEditingId(null);
