                                            value={editValues.current}
                                            onChange={(e) => setEditValues({...editValues, current: Number(e.target.value)})}
                                            autoFocus
                                         />
                                     </div>
                                     <div className="w-full">
                                         <label className="text-xs text-gray-500 font-medium block mb-1">Target</label>
                                         <input 
                                            type="number" 
                                            className="w-full border border-gray-300 rounded p-1.5 text-center font-bold text-slate-900 bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
