                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Stage</label>
                            <select 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.pipelineStage}
                                onChange={(e) => setEditingClient({...editingClient, pipelineStage: e.target.value as PipelineStage})}
                            >
                                {stages.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Notes</label>
                        <textarea 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none bg-white text-slate-900"
                            rows={3}
                            value={editingClient.notes}
                            onChange={(e) => setEditingClient({...editingClient, notes: e.target.value})}
                        />
                    </div>

                    <div className="pt-2 flex gap-3">
                        <button 
                            onClick={() => setIsEditModalOpen(false)}
                            className="flex-1 py-2.5 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={handleSaveEdit}
                            className="flex-1 py-2.5 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2"
                        >
                            <Save size={16} /> Save Changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

import React, { useState, useEffect } from 'react';
import { MOCK_GOALS } from '../services/mockData';
import { Target, TrendingUp, Edit2, X, Check, Calendar, BarChart3, Plus, Trash2 } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

type GoalPeriod = 'WEEKLY' | 'MONTHLY' | 'YEARLY';

interface Goal {
    id: string;
    title: string;
    current: number;
    target: number;
    unit: string;
}

const Goals: React.FC = () => {
    // Initialize goals for all periods
    const [allGoals, setAllGoals] = useState<Record<GoalPeriod, Goal[]>>(() => {
        const saved = localStorage.getItem('arise_goals_v2');
        if (saved) return JSON.parse(saved);

        // Generate defaults based on MOCK_GOALS (assumed Monthly)
        const monthly = MOCK_GOALS;
        const weekly = monthly.map(g => ({
            ...g, 
            id: `w-${g.id}`,
            current: Math.round(g.current / 4),
            target: Math.round(g.target / 4)
        }));
        const yearly = monthly.map(g => ({
            ...g, 
            id: `y-${g.id}`,
            current: Math.round(g.current * 12), // Mocking YTD/Yearly projection
            target: Math.round(g.target * 12)
        }));

        return {
            WEEKLY: weekly,
            MONTHLY: monthly,
            YEARLY: yearly
        };
    });

    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('MONTHLY');
    const [editingId, setEditingId] = useState<string | null>(null);

    // Use strings for edit values to avoid "stable 0" issue and allow empty inputs
    const [editValues, setEditValues] = useState({ current: '', target: '' });

    // Add Goal Modal State
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [newGoal, setNewGoal] = useState({ title: '', target: '', current: '', unit: '$' });

    useEffect(() => {
        localStorage.setItem('arise_goals_v2', JSON.stringify(allGoals));
    }, [allGoals]);

    const handleEditClick = (goal: Goal) => {
        setEditingId(goal.id);
        // Convert to string on open so user sees current value but can clear it
        setEditValues({ current: goal.current.toString(), target: goal.target.toString() });
    };

    const handleSave = (id: string) => {
        // Parse back to numbers on save
        const currentVal = parseFloat(editValues.current) || 0;
        const targetVal = parseFloat(editValues.target) || 0;

        const updatedGoals = allGoals[activePeriod].map((g) => 
            g.id === id ? { ...g, current: currentVal, target: targetVal } : g
        );

        setAllGoals(prev => ({
            ...prev,
            [activePeriod]: updatedGoals
        }));
        setEditingId(null);
    };

    const handleDelete = (id: string) => {
        if (window.confirm("Are you sure you want to delete this goal?")) {
            setAllGoals(prev => ({
                ...prev,
                [activePeriod]: prev[activePeriod].filter(g => g.id !== id)
            }));
        }
    };

    const handleAddGoal = () => {
        if (!newGoal.title || !newGoal.target) return;

        const goal: Goal = {
            id: `g-${Date.now()}`,
            title: newGoal.title,
            current: Number(newGoal.current) || 0,
            target: Number(newGoal.target),
            unit: newGoal.unit
        };

        setAllGoals(prev => ({
            ...prev,
            [activePeriod]: [...prev[activePeriod], goal]
        }));

        setIsAddModalOpen(false);
        setNewGoal({ title: '', target: '', current: '', unit: '$' });
    };

    const currentGoals = allGoals[activePeriod];

    // Class to hide browser default number spinners and force white background
    const numberInputClass = "w-full border border-gray-300 rounded p-1.5 text-center font-bold text-slate-900 bg-white focus:ring-2 focus:ring-indigo-500 outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none";

    return (
        <div className="animate-fade-in space-y-6 relative">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Financial Goals</h2>
                    <p className="text-slate-500 text-sm">Track your performance against {activePeriod.toLowerCase()} targets.</p>
                </div>

                <div className="flex items-center gap-2">
                    <div className="bg-white p-1 rounded-lg border border-gray-200 shadow-sm flex">
                        {(['WEEKLY', 'MONTHLY', 'YEARLY'] as GoalPeriod[]).map((period) => (
                            <button
                                key={period}
                                onClick={() => setActivePeriod(period)}
                                className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${
                                    activePeriod === period 
                                        ? 'bg-indigo-600 text-white shadow-sm' 
                                        : 'text-slate-500 hover:bg-gray-50'
                                }`}
                            >
                                {period}
                            </button>
                        ))}
                    </div>
                    <button 
                        onClick={() => setIsAddModalOpen(true)}
                        className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-colors"
                        title="Add New Goal"
                    >
                        <Plus size={20} />
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {currentGoals.map((goal, index) => {
                    const percentage = goal.target > 0 ? Math.min(100, Math.round((goal.current / goal.target) * 100)) : 0;
                    const data = [
                        { name: 'Completed', value: goal.current },
                        { name: 'Remaining', value: Math.max(0, goal.target - goal.current) }
                    ];
                    const COLORS = ['#4f46e5', '#e2e8f0'];
                    const isEditing = editingId === goal.id;

                    return (
                        <div key={goal.id} className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center text-center relative overflow-hidden group">
                             {!isEditing && (
                                 <div className="absolute top-0 left-0 w-full h-1 bg-gray-100">
                                     <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${percentage}%`}}></div>
                                 </div>
                             )}

                             {!isEditing && (
                                <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                    <button 
                                        onClick={() => handleEditClick(goal)}
                                        className="p-1.5 text-gray-400 hover:text-indigo-600 rounded-full hover:bg-indigo-50"
                                        title="Edit Goal"
                                    >
                                        <Edit2 size={14} />
                                    </button>
                                    <button 
                                        onClick={() => handleDelete(goal.id)}
                                        className="p-1.5 text-gray-400 hover:text-red-600 rounded-full hover:bg-red-50"
                                        title="Delete Goal"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                             )}

                             <h3 className="text-slate-500 font-medium text-sm uppercase tracking-wide mt-2">{goal.title}</h3>

                             {isEditing ? (
                                 <div className="flex-1 flex flex-col justify-center items-center w-full gap-3 py-4 animate-fade-in">
                                     <div className="w-full">
                                         <label className="text-xs text-gray-500 font-medium block mb-1">Current</label>
                                         <input 
                                            type="number" 
                                            className={numberInputClass}
                                            value={editValues.current}
                                            onChange={(e) => setEditValues({...editValues, current: e.target.value})}
                                            autoFocus
                                         />
                                     </div>
                                     <div className="w-full">
                                         <label className="text-xs text-gray-500 font-medium block mb-1">Target</label>
                                         <input 
                                            type="number" 
                                            className={numberInputClass}
                                            value={editValues.target}
                                            onChange={(e) => setEditValues({...editValues, target: e.target.value})}
                                         />
                                     </div>
                                     <div className="flex gap-2 mt-2 w-full">
                                         <button onClick={() => setEditingId(null)} className="flex-1 p-1.5 bg-gray-100 text-gray-600 rounded hover:bg-gray-200 transition-colors">
                                            <X size={16} className="mx-auto" />
                                         </button>
                                         <button onClick={() => handleSave(goal.id)} className="flex-1 p-1.5 bg-indigo-600 text-white rounded hover:bg-indigo-700 transition-colors">
                                            <Check size={16} className="mx-auto" />
                                         </button>
                                     </div>
                                 </div>
                             ) : (
                                 <>
                                    <div className="h-32 w-32 my-4 relative">
                                        <ResponsiveContainer width="100%" height="100%">
                                            <PieChart>
                                                <Pie
                                                    data={data}
                                                    cx="50%"
                                                    cy="50%"
                                                    innerRadius={35}
                                                    outerRadius={45}
                                                    startAngle={90}
                                                    endAngle={-270}
                                                    dataKey="value"
                                                    stroke="none"
                                                >
                                                    {data.map((entry, index) => (
                                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                                    ))}
                                                </Pie>
                                            </PieChart>
                                        </ResponsiveContainer>
                                        <div className="absolute inset-0 flex items-center justify-center flex-col pointer-events-none">
                                            <span className="text-xl font-bold text-slate-800">{percentage}%</span>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className="text-2xl font-bold text-slate-900">
                                            {goal.unit === '$' ? `$${goal.current.toLocaleString()}` : goal.current}
                                        </span>
                                        <span className="text-gray-400 text-sm">/ {goal.unit === '$' ? `$${goal.target.toLocaleString()}` : goal.target}</span>
                                    </div>
                                    {percentage >= 100 && (
                                        <span className="px-2 py-1 bg-green-100 text-green-700 text-xs rounded-full font-bold animate-pulse">Goal Hit!</span>
                                    )}
                                 </>
                             )}
                        </div>
                    );
                })}
            </div>

            {/* Bonus Section */}
            <div className="bg-gradient-to-r from-indigo-600 to-purple-600 rounded-xl p-8 text-white shadow-lg flex flex-col md:flex-row justify-between items-center gap-6">
                <div>
                    <h3 className="text-2xl font-bold mb-2">
                        {activePeriod === 'WEEKLY' ? 'Weekly Sprint Bonus' : activePeriod === 'MONTHLY' ? 'Monthly Pace Bonus' : 'Annual President\'s Club'}
                    </h3>
                    <p className="text-indigo-100 max-w-xl">
                        {activePeriod === 'WEEKLY' 
                            ? "Close 2 more apps this week to unlock the $500 fast start bonus."
                            : activePeriod === 'MONTHLY'
                            ? "You are on track to hit the 'Elite Producer' bonus tier for October."
                            : "Only $16,000 more in premium needed to qualify for the President's Club Trip to Cabo."}
                    </p>
                </div>
                <div className="h-16 w-16 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-sm shrink-0">
                    <Target size={32} className="text-white" />
                </div>
            </div>

            {/* Add Goal Modal */}
            {isAddModalOpen && (
                <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm ring-1 ring-black/5 animate-fade-in overflow-hidden">
                        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <Target size={18} className="text-indigo-600" /> New {activePeriod.toLowerCase()} Goal
                            </h3>
                            <button onClick={() => setIsAddModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                                <X size={20} />
                            </button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Goal Title</label>
                                <input 
                                    type="text"
                                    autoFocus
                                    className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                    placeholder="e.g. Total Appointments"
                                    value={newGoal.title}
                                    onChange={(e) => setNewGoal({...newGoal, title: e.target.value})}
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Target</label>
                                    <input 
                                        type="number"
                                        className={numberInputClass}
                                        placeholder="100"
                                        value={newGoal.target}
                                        onChange={(e) => setNewGoal({...newGoal, target: e.target.value})}
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Current</label>
                                    <input 
                                        type="number"
                                        className={numberInputClass}
                                        placeholder="0"
                                        value={newGoal.current}
                                        onChange={(e) => setNewGoal({...newGoal, current: e.target.value})}
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Unit Type</label>
                                <select
                                    className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                    value={newGoal.unit}
                                    onChange={(e) => setNewGoal({...newGoal, unit: e.target.value})}
                                >
                                    <option value="$">Currency ($)</option>
                                    <option value="Apps">Applications</option>
                                    <option value="Appts">Appointments</option>
                                    <option value="Calls">Calls</option>
                                    <option value="Recruits">Recruits</option>
                                    <option value="Units">Generic Units</option>
                                </select>
                            </div>

                            <button 
                                onClick={handleAddGoal}
                                className="w-full py-2.5 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors shadow-sm mt-2"
                            >
                                Create Goal
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Goals;

import React, { useState } from 'react';
import { PipelineStage, Client } from '../types';
import { MoreHorizontal, Plus, Calendar, X, ChevronRight, ChevronLeft, Phone, MapPin, Edit2, Save, Cake, GripVertical, Upload, ArrowRight, FileSpreadsheet } from 'lucide-react';

interface PipelineProps {
    clients: Client[];
    currentUserId: string; // ID of the logged-in agent
    onUpdateClients: (clients: Client[]) => void;
}

const Pipeline: React.FC<PipelineProps> = ({ clients, currentUserId, onUpdateClients }) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // Import Modal State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importStep, setImportStep] = useState<'UPLOAD' | 'MAP'>('UPLOAD');
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<Record<string, string>[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      stage: ''
  });

  const [newLead, setNewLead] = useState({ firstName: '', lastName: '', email: '', stage: PipelineStage.NEW_LEAD });
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Drag and Drop State
  const [draggedClientId, setDraggedClientId] = useState<string | null>(null);
  const [targetStage, setTargetStage] = useState<PipelineStage | null>(null);

  const stages = Object.values(PipelineStage);

  const getClientsByStage = (stage: PipelineStage) => {
    return clients.filter(c => c.pipelineStage === stage);
  };

  const moveStage = (clientId: string, direction: 'next' | 'prev') => {
    onUpdateClients(clients.map(client => {
      if (client.id !== clientId) return client;

      const currentIndex = stages.indexOf(client.pipelineStage);
      let newIndex = currentIndex;

      if (direction === 'next' && currentIndex < stages.length - 1) {
        newIndex++;
      } else if (direction === 'prev' && currentIndex > 0) {
        newIndex--;
      }

      return { ...client, pipelineStage: stages[newIndex] };
    }));
  };

  const handleAddLead = () => {
    if (!newLead.firstName || !newLead.lastName) return;

    const lead: Client = {
        id: Date.now().toString(),
        agentId: currentUserId,
        firstName: newLead.firstName,
        lastName: newLead.lastName,
        email: newLead.email,
        phone: '',
        address: '',
        policies: [],
        notes: 'New lead added manually',
        pipelineStage: newLead.stage,
        leadSource: 'Manual',
        lastContactDate: new Date().toISOString().split('T')[0]
    };

    onUpdateClients([...clients, lead]);
    setIsAddModalOpen(false);
    setNewLead({ firstName: '', lastName: '', email: '', stage: PipelineStage.NEW_LEAD });
  };

  const openEditModal = (client: Client) => {
      setEditingClient({ ...client });
      setIsEditModalOpen(true);
  };

  const handleSaveEdit = () => {
      if (!editingClient) return;
      onUpdateClients(clients.map(c => c.id === editingClient.id ? editingClient : c));
      setIsEditModalOpen(false);
      setEditingClient(null);
  };

  // --- Drag and Drop Handlers ---

  const handleDragStart = (e: React.DragEvent, clientId: string) => {
      setDraggedClientId(clientId);
      e.dataTransfer.setData('clientId', clientId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault(); // Necessary to allow dropping
      if (targetStage !== stage) {
          setTargetStage(stage);
      }
  };

  const handleDrop = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault();
      const clientId = e.dataTransfer.getData('clientId');

      if (clientId) {
          onUpdateClients(clients.map(client => {
              if (client.id === clientId) {
                  return { ...client, pipelineStage: stage };
              }
              return client;
          }));
      }

      setDraggedClientId(null);
      setTargetStage(null);
  };

  // --- Import Handlers ---

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const text = evt.target?.result as string;
            // Basic CSV parse
            const lines = text.split(/\r\n|\n/).filter(line => line.trim() !== '');
            if (lines.length > 0) {
                const headers = lines[0].split(',').map(h => h.trim());
                setCsvHeaders(headers);

                const data = lines.slice(1).map(line => {
                    const values = line.split(',');
                    const row: Record<string, string> = {};
                    headers.forEach((h, i) => {
                        row[h] = values[i]?.trim() || '';
                    });
                    return row;
                });
                setCsvData(data);
                setImportStep('MAP');

                // Auto-guess mapping
                const newMapping = { ...fieldMapping };
                headers.forEach(h => {
                    const lowerH = h.toLowerCase();
                    if (lowerH.includes('first')) newMapping.firstName = h;
                    else if (lowerH.includes('last')) newMapping.lastName = h;
                    else if (lowerH.includes('email')) newMapping.email = h;
                    else if (lowerH.includes('phone')) newMapping.phone = h;
                    else if (lowerH.includes('stage') || lowerH.includes('status')) newMapping.stage = h;
                });
                setFieldMapping(newMapping);
            }
        };
        reader.readAsText(file);
    }
  };

  const executeImport = () => {
    const newClients = csvData.map(row => ({
        id: `imported-${Date.now()}-${Math.random()}`,
        agentId: currentUserId,
        firstName: row[fieldMapping.firstName] || 'Unknown',
        lastName: row[fieldMapping.lastName] || 'Client',
        email: row[fieldMapping.email] || '',
        phone: row[fieldMapping.phone] || '',
        address: '',
        policies: [],
        notes: 'Imported via CSV',
        pipelineStage: (row[fieldMapping.stage] as PipelineStage) || PipelineStage.NEW_LEAD,
        leadSource: 'Import',
        lastContactDate: new Date().toISOString().split('T')[0]
    }));

    onUpdateClients([...clients, ...newClients]);
    setIsImportModalOpen(false);
    setImportStep('UPLOAD');
    setCsvData([]);
    setCsvHeaders([]);
  };

  return (
    <div className="h-full flex flex-col animate-fade-in relative">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Leads Pipeline</h2>
        <div className="flex gap-2">
            <button className="px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors">
                Filter View
            </button>
            <button 
                onClick={() => setIsImportModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors"
            >
                <Upload size={16} /> Import
            </button>
            <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
            >
                <Plus size={16} /> Add Lead
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-x-auto pb-4">
        <div className="flex gap-4 h-full min-w-max">
          {stages.map((stage) => {
            const stageClients = getClientsByStage(stage);
            const isDragTarget = targetStage === stage && draggedClientId !== null;

            return (
              <div 
                key={stage} 
                className={`w-80 flex flex-col rounded-xl border transition-all duration-200 h-full ${
                    isDragTarget 
                        ? 'bg-indigo-50 border-indigo-300 ring-2 ring-indigo-200 shadow-lg scale-[1.01]' 
                        : 'bg-gray-50/50 border-gray-100'
                }`}
                onDragOver={(e) => handleDragOver(e, stage)}
                onDrop={(e) => handleDrop(e, stage)}
              >
                {/* Stage Header */}
                <div className={`p-4 border-b rounded-t-xl backdrop-blur-sm transition-colors ${
                    isDragTarget ? 'bg-indigo-100/50 border-indigo-200' : 'border-gray-100 bg-white/50'
                }`}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className={`font-semibold ${isDragTarget ? 'text-indigo-800' : 'text-slate-700'}`}>{stage}</h3>
                    <MoreHorizontal size={16} className="text-gray-400 cursor-pointer" />
                  </div>
                  <div className="flex justify-between items-center text-xs text-gray-500">
                    <span>{stageClients.length} Leads</span>
                  </div>
                </div>

                {/* Cards */}
                <div className="p-3 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                  {stageClients.map((client) => (
                    <div 
                        key={client.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, client.id)}
                        className={`bg-white p-4 rounded-lg shadow-sm border border-gray-100 hover:shadow-md transition-all group relative cursor-grab active:cursor-grabbing ${
                            draggedClientId === client.id ? 'opacity-40 border-dashed border-indigo-300' : ''
                        }`}
                    >
                      {/* Grip Icon for affordance */}
                      <div className="absolute top-1/2 left-1 -translate-y-1/2 opacity-0 group-hover:opacity-30 transition-opacity">
                          <GripVertical size={16} />
                      </div>

                      {/* Name and Source */}
                      <div className="flex justify-between items-start mb-2 pl-2">
                         <span className="font-bold text-slate-800 text-sm truncate max-w-[140px] block" title={`${client.firstName} ${client.lastName}`}>
                            {client.firstName} {client.lastName}
                         </span>
                         {client.leadSource && (
                             <span className="text-[10px] uppercase tracking-wider font-bold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-100">
                                 {client.leadSource}
                             </span>
                         )}
                      </div>

                      {/* Contact Details */}
                      <div className="space-y-2 mt-3 pl-2">
                          <div className="flex items-center text-xs text-gray-500">
                              <Phone size={12} className="mr-2 text-slate-400" />
                              {client.phone ? client.phone : <span className="italic text-gray-400">No phone</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Cake size={12} className="mr-2 text-slate-400" />
                              {client.dateOfBirth ? client.dateOfBirth : <span className="italic text-gray-400">No DOB</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <MapPin size={12} className="mr-2 text-slate-400" />
                              {client.address ? <span className="truncate max-w-[180px]">{client.address}</span> : <span className="italic text-gray-400">No State/Address</span>}
                          </div>

                          {/* Last Contact Footer */}
                          <div className="flex items-center text-xs text-slate-400 pt-2 border-t border-gray-50 mt-2">
                              <Calendar size={12} className="mr-2 opacity-70" />
                              Last Contact: {client.lastContactDate}
                          </div>
                      </div>

                      {/* Action Buttons Overlay (Still available if preferred over drag) */}
                      <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 rounded-lg border border-indigo-100 z-10 pointer-events-none">
                          <div className="flex items-center gap-2 pointer-events-auto">
                              <button 
                                onClick={() => moveStage(client.id, 'prev')}
                                disabled={stage === PipelineStage.NEW_LEAD}
                                className="p-2 rounded-full bg-gray-100 hover:bg-gray-200 disabled:opacity-30 text-gray-600 border border-gray-200"
                                title="Move Back"
                              >
                                 <ChevronLeft size={16} />
                              </button>

                              <button 
                                 onClick={() => openEditModal(client)}
                                 className="flex items-center gap-1 px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-lg shadow-md hover:bg-indigo-700 transition-colors"
                              >
                                 <Edit2 size={12} /> Edit Lead
                              </button>

                              <button 
                                 onClick={() => moveStage(client.id, 'next')}
                                 disabled={stage === PipelineStage.ISSUED}
                                 className="p-2 rounded-full bg-indigo-50 hover:bg-indigo-100 disabled:opacity-30 text-indigo-600 border border-indigo-100"
                                 title="Move Next"
                              >
                                 <ChevronRight size={16} />
                              </button>
                          </div>
                      </div>
                    </div>
                  ))}
                  <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="w-full py-2 border border-dashed border-gray-300 text-gray-400 rounded-lg text-sm hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
                  >
                      <Plus size={14} /> Add Card
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Import Modal */}
      {isImportModalOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-2xl ring-1 ring-black/5 flex flex-col max-h-[80vh]">
                  <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                      <h3 className="font-bold text-xl text-slate-800 flex items-center gap-2">
                          <Upload size={20} className="text-indigo-600" /> Import Leads
                      </h3>
                      <button onClick={() => { setIsImportModalOpen(false); setImportStep('UPLOAD'); }} className="text-gray-400 hover:text-gray-600">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 flex-1 overflow-y-auto">
                      {importStep === 'UPLOAD' ? (
                          <div className="flex flex-col items-center justify-center h-full space-y-6">
                              <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center">
                                  <FileSpreadsheet size={40} className="text-indigo-600" />
                              </div>
                              <div className="text-center">
                                  <h4 className="text-lg font-bold text-slate-800">Upload CSV File</h4>
                                  <p className="text-slate-500 text-sm mt-1">Select a CSV file containing your lead data.</p>
                              </div>
                              <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 text-slate-700 font-medium py-2 px-6 rounded-lg shadow-sm transition-colors">
                                  <span className="flex items-center gap-2"><Upload size={16} /> Choose File</span>
                                  <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
                              </label>
                              <div className="bg-slate-50 p-4 rounded-lg text-xs text-slate-500 max-w-md text-center border border-slate-200">
                                  Tip: Ensure your file has a header row. We'll help you map the columns in the next step.
                              </div>
                          </div>
                      ) : (
                          <div className="space-y-6">
                              <div className="bg-green-50 border border-green-200 p-4 rounded-lg flex items-start gap-3">
                                  <CheckCircle2 size={20} className="text-green-600 shrink-0 mt-0.5" />
                                  <div>
                                      <h4 className="font-bold text-green-900 text-sm">File Loaded Successfully</h4>
                                      <p className="text-green-700 text-xs mt-1">Found {csvData.length} rows and {csvHeaders.length} columns. Please map the fields below.</p>
                                  </div>
                              </div>

                              <div className="space-y-4">
                                  {Object.keys(fieldMapping).map((systemField) => (
                                      <div key={systemField} className="grid grid-cols-2 gap-4 items-center">
                                          <label className="text-sm font-bold text-slate-600 uppercase flex justify-end">
                                              {systemField.replace(/([A-Z])/g, ' $1').trim()}
                                          </label>
                                          <div className="flex items-center gap-2">
                                              <ArrowRight size={14} className="text-gray-300" />
                                              <select 
                                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
                                                  value={fieldMapping[systemField]}
                                                  onChange={(e) => setFieldMapping({...fieldMapping, [systemField]: e.target.value})}
                                              >
                                                  <option value="">-- Select Column --</option>
                                                  {csvHeaders.map(header => (
                                                      <option key={header} value={header}>{header}</option>
                                                  ))}
                                              </select>
                                          </div>
                                      </div>
                                  ))}
                              </div>
                          </div>
                      )}
                  </div>

                  <div className="p-5 border-t border-gray-100 bg-gray-50 rounded-b-xl flex justify-end">
                      {importStep === 'MAP' && (
                          <button 
                              onClick={executeImport}
                              disabled={!fieldMapping.firstName || !fieldMapping.lastName}
                              className="px-6 py-2.5 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 shadow-md"
                          >
                              Complete Import <ArrowRight size={16} />
                          </button>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Add Lead Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-white/90 backdrop-blur-md">
            <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-md ring-1 ring-black/5">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-white rounded-t-xl">
                    <h3 className="font-bold text-slate-800">Add New Lead</h3>
                    <button onClick={() => setIsAddModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-6 space-y-4 bg-white">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">First Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newLead.firstName}
                                onChange={(e) => setNewLead({...newLead, firstName: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Last Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newLead.lastName}
                                onChange={(e) => setNewLead({...newLead, lastName: e.target.value})}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                        <input 
                            type="email" 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={newLead.email}
                            onChange={(e) => setNewLead({...newLead, email: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Starting Stage</label>
                        <select 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm outline-none bg-white text-slate-900"
                            value={newLead.stage}
                            onChange={(e) => setNewLead({...newLead, stage: e.target.value as PipelineStage})}
                        >
                            {stages.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                    <button 
                        onClick={handleAddLead}
                        className="w-full py-2 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-colors mt-2"
                    >
                        Create Lead
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Edit Lead Modal */}
      {isEditModalOpen && editingClient && (
        <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-white/90 backdrop-blur-md">
            <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-lg ring-1 ring-black/5 animate-fade-in">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-white rounded-t-xl">
                    <h3 className="font-bold text-slate-800 flex items-center gap-2">
                        <Edit2 size={18} className="text-indigo-600" /> Edit Lead Details
                    </h3>
                    <button onClick={() => setIsEditModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-6 space-y-4 max-h-[80vh] overflow-y-auto bg-white">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">First Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.firstName}
                                onChange={(e) => setEditingClient({...editingClient, firstName: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Last Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.lastName}
                                onChange={(e) => setEditingClient({...editingClient, lastName: e.target.value})}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Phone</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.phone}
                                onChange={(e) => setEditingClient({...editingClient, phone: e.target.value})}
                                placeholder="(555) 123-4567"
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Date of Birth</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.dateOfBirth || ''}
                                onChange={(e) => setEditingClient({...editingClient, dateOfBirth: e.target.value})}
                                placeholder="YYYY-MM-DD"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Email</label>
                        <input 
                            type="email" 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={editingClient.email}
                            onChange={(e) => setEditingClient({...editingClient, email: e.target.value})}
                        />
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Address / State</label>
                        <div className="relative">
                            <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg pl-8 pr-2 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.address}
                                onChange={(e) => setEditingClient({...editingClient, address: e.target.value})}
                                placeholder="123 Main St, State, Zip"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Lead Type</label>
                            <select 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.leadSource}
                                onChange={(e) => setEditingClient({...editingClient, leadSource: e.target.value})}
                            >
                                <option value="Manual">Manual</option>
                                <option value="Facebook Ad">Facebook Ad</option>
                                <option value="Website">Website</option>
                                <option value="Referral">Referral</option>
                                <option value="Direct Mail">Direct Mail</option>
                                <option value="Cold Call">Cold Call</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Stage</label>
                            <select 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.pipelineStage}
                                onChange={(e) => setEditingClient({...editingClient, pipelineStage: e.target.value as PipelineStage})}
                            >
                                {stages.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Notes</label>
                        <textarea 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none bg-white text-slate-900"
                            rows={3}
                            value={editingClient.notes}
                            onChange={(e) => setEditingClient({...editingClient, notes: e.target.value})}
                        />
                    </div>

                    <div className="pt-2 flex gap-3">
                        <button 
                            onClick={() => setIsEditModalOpen(false)}
                            className="flex-1 py-2.5 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={handleSaveEdit}
                            className="flex-1 py-2.5 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2"
                        >
                            <Save size={16} /> Save Changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

import React, { useState } from 'react';
import { PipelineStage, Client } from '../types';
import { MoreHorizontal, Plus, Calendar, X, ChevronRight, ChevronLeft, Phone, MapPin, Edit2, Save, Cake, GripVertical, Upload, ArrowRight, FileSpreadsheet, CheckCircle2 } from 'lucide-react';

interface PipelineProps {
    clients: Client[];
    currentUserId: string; // ID of the logged-in agent
    onUpdateClients: (clients: Client[]) => void;
}

const Pipeline: React.FC<PipelineProps> = ({ clients, currentUserId, onUpdateClients }) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // Import Modal State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importStep, setImportStep] = useState<'UPLOAD' | 'MAP'>('UPLOAD');
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<Record<string, string>[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      stage: ''
  });

  const [newLead, setNewLead] = useState({ firstName: '', lastName: '', email: '', stage: PipelineStage.NEW_LEAD });
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Drag and Drop State
  const [draggedClientId, setDraggedClientId] = useState<string | null>(null);
  const [targetStage, setTargetStage] = useState<PipelineStage | null>(null);

  const stages = Object.values(PipelineStage);

  const getClientsByStage = (stage: PipelineStage) => {
    return clients.filter(c => c.pipelineStage === stage);
  };

  const moveStage = (clientId: string, direction: 'next' | 'prev') => {
    onUpdateClients(clients.map(client => {
      if (client.id !== clientId) return client;

      const currentIndex = stages.indexOf(client.pipelineStage);
      let newIndex = currentIndex;

      if (direction === 'next' && currentIndex < stages.length - 1) {
        newIndex++;
      } else if (direction === 'prev' && currentIndex > 0) {
        newIndex--;
      }

      return { ...client, pipelineStage: stages[newIndex] };
    }));
  };

  const handleAddLead = () => {
    if (!newLead.firstName || !newLead.lastName) return;

    const lead: Client = {
        id: Date.now().toString(),
        agentId: currentUserId,
        firstName: newLead.firstName,
        lastName: newLead.lastName,
        email: newLead.email,
        phone: '',
        address: '',
        policies: [],
        notes: 'New lead added manually',
        pipelineStage: newLead.stage,
        leadSource: 'Manual',
        lastContactDate: new Date().toISOString().split('T')[0]
    };

    onUpdateClients([...clients, lead]);
    setIsAddModalOpen(false);
    setNewLead({ firstName: '', lastName: '', email: '', stage: PipelineStage.NEW_LEAD });
  };

  const openEditModal = (client: Client) => {
      setEditingClient({ ...client });
      setIsEditModalOpen(true);
  };

  const handleSaveEdit = () => {
      if (!editingClient) return;
      onUpdateClients(clients.map(c => c.id === editingClient.id ? editingClient : c));
      setIsEditModalOpen(false);
      setEditingClient(null);
  };

  // --- Drag and Drop Handlers ---

  const handleDragStart = (e: React.DragEvent, clientId: string) => {
      setDraggedClientId(clientId);
      e.dataTransfer.setData('clientId', clientId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault(); // Necessary to allow dropping
      if (targetStage !== stage) {
          setTargetStage(stage);
      }
  };

  const handleDrop = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault();
      const clientId = e.dataTransfer.getData('clientId');

      if (clientId) {
          onUpdateClients(clients.map(client => {
              if (client.id === clientId) {
                  return { ...client, pipelineStage: stage };
              }
              return client;
          }));
      }

      setDraggedClientId(null);
      setTargetStage(null);
  };

  // --- Import Handlers ---

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const text = evt.target?.result as string;
            // Basic CSV parse
            const lines = text.split(/\r\n|\n/).filter(line => line.trim() !== '');
            if (lines.length > 0) {
                const headers = lines[0].split(',').map(h => h.trim());
                setCsvHeaders(headers);

                const data = lines.slice(1).map(line => {
                    const values = line.split(',');
                    const row: Record<string, string> = {};
                    headers.forEach((h, i) => {
                        row[h] = values[i]?.trim() || '';
                    });
                    return row;
                });
                setCsvData(data);
                setImportStep('MAP');

                // Auto-guess mapping
                const newMapping = { ...fieldMapping };
                headers.forEach(h => {
                    const lowerH = h.toLowerCase();
                    if (lowerH.includes('first')) newMapping.firstName = h;
                    else if (lowerH.includes('last')) newMapping.lastName = h;
                    else if (lowerH.includes('email')) newMapping.email = h;
                    else if (lowerH.includes('phone')) newMapping.phone = h;
                    else if (lowerH.includes('stage') || lowerH.includes('status')) newMapping.stage = h;
                });
                setFieldMapping(newMapping);
            }
        };
        reader.readAsText(file);
    }
  };

  const executeImport = () => {
    const newClients = csvData.map(row => ({
        id: `imported-${Date.now()}-${Math.random()}`,
        agentId: currentUserId,
        firstName: row[fieldMapping.firstName] || 'Unknown',
        lastName: row[fieldMapping.lastName] || 'Client',
        email: row[fieldMapping.email] || '',
        phone: row[fieldMapping.phone] || '',
        address: '',
        policies: [],
        notes: 'Imported via CSV',
        pipelineStage: (row[fieldMapping.stage] as PipelineStage) || PipelineStage.NEW_LEAD,
        leadSource: 'Import',
        lastContactDate: new Date().toISOString().split('T')[0]
    }));

    onUpdateClients([...clients, ...newClients]);
    setIsImportModalOpen(false);
    setImportStep('UPLOAD');
    setCsvData([]);
    setCsvHeaders([]);
  };

  return (
    <div className="h-full flex flex-col animate-fade-in relative">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Leads Pipeline</h2>
        <div className="flex gap-2">
            <button className="px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors">
                Filter View
            </button>
            <button 
                onClick={() => setIsImportModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors"
            >
                <Upload size={16} /> Import
            </button>
            <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
            >
                <Plus size={16} /> Add Lead
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-x-auto pb-4">
        <div className="flex gap-4 h-full min-w-max">
          {stages.map((stage) => {
            const stageClients = getClientsByStage(stage);
            const isDragTarget = targetStage === stage && draggedClientId !== null;

            return (
              <div 
                key={stage} 
                className={`w-80 flex flex-col rounded-xl border transition-all duration-200 h-full ${
                    isDragTarget 
                        ? 'bg-indigo-50 border-indigo-300 ring-2 ring-indigo-200 shadow-lg scale-[1.01]' 
                        : 'bg-gray-50/50 border-gray-100'
                }`}
                onDragOver={(e) => handleDragOver(e, stage)}
                onDrop={(e) => handleDrop(e, stage)}
              >
                {/* Stage Header */}
                <div className={`p-4 border-b rounded-t-xl backdrop-blur-sm transition-colors ${
                    isDragTarget ? 'bg-indigo-100/50 border-indigo-200' : 'border-gray-100 bg-white/50'
                }`}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className={`font-semibold ${isDragTarget ? 'text-indigo-800' : 'text-slate-700'}`}>{stage}</h3>
                    <MoreHorizontal size={16} className="text-gray-400 cursor-pointer" />
                  </div>
                  <div className="flex justify-between items-center text-xs text-gray-500">
                    <span>{stageClients.length} Leads</span>
                  </div>
                </div>

                {/* Cards */}
                <div className="p-3 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                  {stageClients.map((client) => (
                    <div 
                        key={client.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, client.id)}
                        className={`bg-white p-4 rounded-lg shadow-sm border border-gray-100 hover:shadow-md transition-all group relative cursor-grab active:cursor-grabbing ${
                            draggedClientId === client.id ? 'opacity-40 border-dashed border-indigo-300' : ''
                        }`}
                    >
                      {/* Grip Icon for affordance */}
                      <div className="absolute top-1/2 left-1 -translate-y-1/2 opacity-0 group-hover:opacity-30 transition-opacity">
                          <GripVertical size={16} />
                      </div>

                      {/* Name and Source */}
                      <div className="flex justify-between items-start mb-2 pl-2">
                         <span className="font-bold text-slate-800 text-sm truncate max-w-[140px] block" title={`${client.firstName} ${client.lastName}`}>
                            {client.firstName} {client.lastName}
                         </span>
                         {client.leadSource && (
                             <span className="text-[10px] uppercase tracking-wider font-bold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-100">
                                 {client.leadSource}
                             </span>
                         )}
                      </div>

                      {/* Contact Details */}
                      <div className="space-y-2 mt-3 pl-2">
                          <div className="flex items-center text-xs text-gray-500">
                              <Phone size={12} className="mr-2 text-slate-400" />
                              {client.phone ? client.phone : <span className="italic text-gray-400">No phone</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Cake size={12} className="mr-2 text-slate-400" />
                              {client.dateOfBirth ? client.dateOfBirth : <span className="italic text-gray-400">No DOB</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <MapPin size={12} className="mr-2 text-slate-400" />
                              {client.address ? <span className="truncate max-w-[180px]">{client.address}</span> : <span className="italic text-gray-400">No State/Address</span>}
                          </div>

                          {/* Last Contact Footer */}
                          <div className="flex items-center text-xs text-slate-400 pt-2 border-t border-gray-50 mt-2">
                              <Calendar size={12} className="mr-2 opacity-70" />
                              Last Contact: {client.lastContactDate}
                          </div>
                      </div>

                      {/* Action Buttons Overlay (Still available if preferred over drag) */}
                      <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 rounded-lg border border-indigo-100 z-10 pointer-events-none">
                          <div className="flex items-center gap-2 pointer-events-auto">
                              <button 
                                onClick={() => moveStage(client.id, 'prev')}
                                disabled={stage === PipelineStage.NEW_LEAD}
                                className="p-2 rounded-full bg-gray-100 hover:bg-gray-200 disabled:opacity-30 text-gray-600 border border-gray-200"
                                title="Move Back"
                              >
                                 <ChevronLeft size={16} />
                              </button>

                              <button 
                                 onClick={() => openEditModal(client)}
                                 className="flex items-center gap-1 px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-lg shadow-md hover:bg-indigo-700 transition-colors"
                              >
                                 <Edit2 size={12} /> Edit Lead
                              </button>

                              <button 
                                 onClick={() => moveStage(client.id, 'next')}
                                 disabled={stage === PipelineStage.ISSUED}
                                 className="p-2 rounded-full bg-indigo-50 hover:bg-indigo-100 disabled:opacity-30 text-indigo-600 border border-indigo-100"
                                 title="Move Next"
                              >
                                 <ChevronRight size={16} />
                              </button>
                          </div>
                      </div>
                    </div>
                  ))}
                  <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="w-full py-2 border border-dashed border-gray-300 text-gray-400 rounded-lg text-sm hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
                  >
                      <Plus size={14} /> Add Card
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Import Modal */}
      {isImportModalOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-2xl ring-1 ring-black/5 flex flex-col max-h-[80vh]">
                  <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                      <h3 className="font-bold text-xl text-slate-800 flex items-center gap-2">
                          <Upload size={20} className="text-indigo-600" /> Import Leads
                      </h3>
                      <button onClick={() => { setIsImportModalOpen(false); setImportStep('UPLOAD'); }} className="text-gray-400 hover:text-gray-600">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 flex-1 overflow-y-auto">
                      {importStep === 'UPLOAD' ? (
                          <div className="flex flex-col items-center justify-center h-full space-y-6">
                              <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center">
                                  <FileSpreadsheet size={40} className="text-indigo-600" />
                              </div>
                              <div className="text-center">
                                  <h4 className="text-lg font-bold text-slate-800">Upload CSV File</h4>
                                  <p className="text-slate-500 text-sm mt-1">Select a CSV file containing your lead data.</p>
                              </div>
                              <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 text-slate-700 font-medium py-2 px-6 rounded-lg shadow-sm transition-colors">
