export enum PolicyType {
  TERM = 'Term Life',
  WHOLE = 'Whole Life',
  IUL = 'IUL',
  ANNUITY = 'Annuity',
  FINAL_EXPENSE = 'Final Expense',
  HEALTH = 'Health'
}

export enum PolicyStatus {
  ACTIVE = 'Active',
  PENDING = 'Pending',
  EXPIRED = 'Expired',
  CANCELLED = 'Cancelled',
