import { MOCK_TEAM } from '../services/mockData';
import { Trophy, TrendingUp, Users, AlertCircle, X, ChevronRight, UserPlus, Phone, FileText, CheckCircle2, Clock, Plus, BarChart3, Download, Edit2, Save, Mail, GripVertical } from 'lucide-react';
import { UserProfile, TeamMember } from '../types';

interface ManagerDashboardProps {
  userProfile?: UserProfile;
}

interface Recruit {
    id: string;
    name: string;
    email?: string;
    phone?: string;
    source: string;
    stage: 'New' | 'Interview' | 'Licensing' | 'Onboarding' | 'Contracted';
    dateAdded: string;
    notes?: string;
}

const ManagerDashboard: React.FC<ManagerDashboardProps> = ({ userProfile }) => {
    // --- State Management ---

    // Team Members (Agents) - Initialized from Mock, but now mutable
    const [teamMembers, setTeamMembers] = useState<TeamMember[]>(MOCK_TEAM);

    // Recruits
    const [recruits, setRecruits] = useState<Recruit[]>([
        { id: 'r1', name: 'David Wallace', source: 'LinkedIn', stage: 'Interview', dateAdded: '2024-10-01', notes: 'Strong sales background.' },
        { id: 'r2', name: 'Karen Filippelli', source: 'Referral', stage: 'Licensing', dateAdded: '2024-09-25', notes: 'Scheduled for exam on Friday.' },
        { id: 'r3', name: 'Danny Cordray', source: 'Cold Outreach', stage: 'New', dateAdded: '2024-10-05', notes: '' },
        { id: 'r4', name: 'Roy Anderson', source: 'Job Board', stage: 'New', dateAdded: '2024-10-06', notes: '' },
        { id: 'r5', name: 'Jan Levinson', source: 'Former Agent', stage: 'Onboarding', dateAdded: '2024-09-15', notes: 'Waiting on E&O proof.' },
    ]);

    // Modals
    const [isRecruitModalOpen, setIsRecruitModalOpen] = useState(false);
    const [isActiveAgentsModalOpen, setIsActiveAgentsModalOpen] = useState(false);
    const [isLeaderboardModalOpen, setIsLeaderboardModalOpen] = useState(false);

    // Edit Recruit Modal
    const [editingRecruit, setEditingRecruit] = useState<Recruit | null>(null);

    // Add Recruit Form State
    const [isAddingRecruit, setIsAddingRecruit] = useState(false);
    const [newRecruitForm, setNewRecruitForm] = useState({ name: '', source: 'LinkedIn', email: '', phone: '' });

    // Drag and Drop State
    const [draggedRecruitId, setDraggedRecruitId] = useState<string | null>(null);
    const [dragOverStage, setDragOverStage] = useState<string | null>(null);

    // Filter for Active Agents (excluding Admin/Manager roles generally, or just showing everyone)
    const activeAgents = teamMembers.filter(m => m.role === 'AGENT' || m.role === 'RECRUIT');

    // --- Logic ---

    // Move recruit via button (legacy support)
    const moveRecruitNext = (id: string) => {
        const recruit = recruits.find(r => r.id === id);
        if (!recruit) return;

        const stages: Recruit['stage'][] = ['New', 'Interview', 'Licensing', 'Onboarding', 'Contracted'];
        const currentIndex = stages.indexOf(recruit.stage);

        if (currentIndex < stages.length - 1) {
            updateRecruitStage(id, stages[currentIndex + 1]);
        }
    };

    // Central function to handle stage changes and conversion
    const updateRecruitStage = (id: string, newStage: Recruit['stage']) => {
        if (newStage === 'Contracted') {
            // Convert to Agent
            const recruit = recruits.find(r => r.id === id);
            if (recruit) {
                if (window.confirm(`Promote ${recruit.name} to Active Agent? This will move them to your roster.`)) {
                    const newAgent: TeamMember = {
                        id: `agent-${Date.now()}`,
                        name: recruit.name,
                        role: 'AGENT',
                        production: 0,
                        activePolicies: 0,
                        avatarUrl: `https://ui-avatars.com/api/?name=${recruit.name}&background=random`
                    };
                    setTeamMembers(prev => [...prev, newAgent]);
                    setRecruits(prev => prev.filter(r => r.id !== id));
                }
            }
        } else {
            // Just move stage
            setRecruits(prev => prev.map(r => r.id === id ? { ...r, stage: newStage } : r));
        }
    };

    // Add Recruit
    const handleAddRecruit = () => {
        if (!newRecruitForm.name) return;

        const newRecruit: Recruit = {
            id: `r-${Date.now()}`,
            name: newRecruitForm.name,
            source: newRecruitForm.source,
            email: newRecruitForm.email,
            phone: newRecruitForm.phone,
            stage: 'New',
            dateAdded: new Date().toISOString().split('T')[0],
            notes: ''
        };

        setRecruits([...recruits, newRecruit]);
        setIsAddingRecruit(false);
        setNewRecruitForm({ name: '', source: 'LinkedIn', email: '', phone: '' });
    };

    // Save Edit
    const handleSaveRecruit = () => {
        if (editingRecruit) {
            setRecruits(prev => prev.map(r => r.id === editingRecruit.id ? editingRecruit : r));
            setEditingRecruit(null);
        }
    };

    // --- Drag and Drop Handlers ---

    const handleDragStart = (e: React.DragEvent, id: string) => {
        setDraggedRecruitId(id);
        e.dataTransfer.setData('recruitId', id);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent, stage: string) => {
        e.preventDefault();
        if (dragOverStage !== stage) {
            setDragOverStage(stage);
        }
    };

