            case 'Onboarding': return 'text-indigo-600 bg-indigo-50/50 border-indigo-100';
            case 'Contracted': return 'text-green-700 bg-green-100 border-green-200';
            default: return 'text-gray-600 bg-gray-50 border-gray-200';
