           <button 
             onClick={() => setIsCopilotOpen(true)}
             className="w-full flex items-center justify-center space-x-2 py-2.5 rounded-xl bg-slate-900 text-white shadow-lg hover:shadow-xl hover:bg-slate-800 transition-all group"
           >
