                            Sign Up
                        </button>
                    </div>

                    <div className="p-8">
                        <div className="mb-6">
                            <h2 className="text-xl font-bold text-slate-800">
                                {activeTab === 'signin' ? 'Welcome Back' : 'Create Account'}
