              {activeView === 'TASKS' && <Tasks />}
              {activeView === 'CALENDAR' && <Calendar />}
              {activeView === 'GOALS' && <Goals />}
              {activeView === 'COMPLIANCE' && <Compliance />}
              {activeView === 'TRAINING' && <Training />}
