export type SubscriptionPlan = 'starter' | 'professional' | 'enterprise';

export enum PolicyType {
  TERM = 'Term Life',
  WHOLE = 'Whole Life',
  IUL = 'IUL',
  ANNUITY = 'Annuity',
  FINAL_EXPENSE = 'Final Expense',
  HEALTH = 'Health'
}

export enum PolicyStatus {
  ACTIVE = 'Active',
  PENDING = 'Pending',
  EXPIRED = 'Expired',
  CANCELLED = 'Cancelled',
  LAPSED = 'Lapsed'
}

export enum PipelineStage {
  NEW_LEAD = 'New Lead',
