import React, { useState, useMemo, useEffect } from 'react';
import { generateSaaSUsers } from '../services/mockData';
import { SaaSUser, Role, SubscriptionStatus, SubscriptionPlan, CommissionRegistry } from '../types';
import { Search, Filter, MoreHorizontal, Shield, CreditCard, User, AlertCircle, TrendingUp, Users, DollarSign, Ban, CheckCircle, ChevronLeft, ChevronRight, Briefcase, X, Save, Mail, Building, Edit2, AlertTriangle, ArrowRight, Lock, Activity, Key, LogIn, Clock, Server, Database, FileSpreadsheet, Upload, Calculator } from 'lucide-react';

const PlatformAdmin: React.FC = () => {
    const [activeTab, setActiveTab] = useState<'USERS' | 'COMMISSIONS'>('USERS');

    // 1. Initialize Large Dataset (Simulating API fetch)
    const [users, setUsers] = useState<SaaSUser[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Edit Modal State
    const [editingUser, setEditingUser] = useState<SaaSUser | null>(null);
    const [editForm, setEditForm] = useState<Partial<SaaSUser>>({});

    // Commission Registry State
    const [commissionRegistry, setCommissionRegistry] = useState<CommissionRegistry>(() => {
        try {
            const saved = localStorage.getItem('arise_commission_registry');
            return saved ? JSON.parse(saved) : {};
        } catch {
            return {};
        }
    });
    const [uploadStatus, setUploadStatus] = useState<string>('');

    // Mock Audit Log Data
    const [auditLog] = useState([
        { id: 1, action: 'Plan Upgrade', user: 'Sarah Connor', details: 'Upgraded to Enterprise', time: '2 mins ago', type: 'success' },
        { id: 2, action: 'Payment Failed', user: 'James Richardson', details: 'Card ending 4242 declined', time: '15 mins ago', type: 'error' },
        { id: 3, action: 'User Login', user: 'Randy Rodriguez', details: 'Successful login from IP 192.168.1.1', time: '1 hour ago', type: 'info' },
        { id: 4, action: 'New Subscription', user: 'Emily Chen', details: 'Started Professional Trial', time: '3 hours ago', type: 'success' },
        { id: 5, action: 'Password Reset', user: 'System Admin', details: 'Reset password for user #492', time: '5 hours ago', type: 'warning' },
    ]);

    useEffect(() => {
        // Simulate network delay for realism
        setTimeout(() => {
            setUsers(generateSaaSUsers(1250));
            setIsLoading(false);
        }, 800);
    }, []);

    // 2. Table State
    const [searchTerm, setSearchTerm] = useState('');
    const [roleFilter, setRoleFilter] = useState<string>('ALL');
    const [statusFilter, setStatusFilter] = useState<string>('ALL');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 10; // Reduced for cleaner look with the log below

    // 3. Derived Stats (Dynamic based on total user base)
    const stats = useMemo(() => {
        const totalMRR = users.reduce((sum, u) => sum + (u.status === 'active' ? u.monthlyFee : 0), 0);
        const activeUsers = users.filter(u => u.status === 'active').length;
        const pastDueUsers = users.filter(u => u.status === 'past_due').length;
        const cancelledUsers = users.filter(u => u.status === 'cancelled').length;
        const churnRate = users.length > 0 ? (cancelledUsers / users.length * 100).toFixed(1) : 0;

        return { totalMRR, activeUsers, pastDueUsers, churnRate };
    }, [users]);

    // 4. Filtering Logic
    const filteredUsers = useMemo(() => {
        return users.filter(user => {
            const matchesSearch = 
                user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                (user.agencyName && user.agencyName.toLowerCase().includes(searchTerm.toLowerCase()));

            const matchesRole = roleFilter === 'ALL' || user.role === roleFilter;
            const matchesStatus = statusFilter === 'ALL' || user.status === statusFilter;

            return matchesSearch && matchesRole && matchesStatus;
        });
    }, [users, searchTerm, roleFilter, statusFilter]);

    // 5. Pagination Logic
    const totalPages = Math.ceil(filteredUsers.length / itemsPerPage);
    const paginatedUsers = filteredUsers.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

    // 6. Actions
    const openEditModal = (user: SaaSUser) => {
        setEditingUser(user);
        setEditForm({ ...user });
    };

    const handleSaveUser = () => {
        if (editingUser && editForm) {
            setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...editForm } as SaaSUser : u));
            setEditingUser(null);
        }
    };

    const handleImpersonate = () => {
        alert(`Simulating login as ${editingUser?.name}. In a real app, this would switch your session.`);
    };

    const handleResetPassword = () => {
        alert(`Password reset email sent to ${editingUser?.email}.`);
    };

    // Quick Filter Action
    const applyQuickFilter = (status: string) => {
        setStatusFilter(status);
        setCurrentPage(1); // Reset to page 1 to ensure results are visible
    };

    // --- Commission CSV Parsers ---

    const parsePercentage = (val: string): number => {
        if (!val) return 0;
        const clean = val.replace('%', '').trim();
        const num = parseFloat(clean);
        return isNaN(num) ? 0 : num / 100;
    };

    const handleGridUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploadStatus('Parsing Matrix CSV...');

        const reader = new FileReader();
        reader.onload = (evt) => {
            const text = evt.target?.result as string;
            const rows = text.split(/\r\n|\n/);

            // Expected Header identifiers to find the start of data
            // We look for 'Company' and 'Product' in a row to identify the header row
            let headerRowIndex = -1;
            for (let i = 0; i < Math.min(rows.length, 20); i++) {
                if (rows[i].includes('Company') && rows[i].includes('Product') && rows[i].includes('FA')) {
                    headerRowIndex = i;
                    break;
                }
            }

            if (headerRowIndex === -1) {
                setUploadStatus('Error: Could not find standard headers (Company, Product, FA, etc.)');
                return;
            }

            const headers = rows[headerRowIndex].split(',').map(h => h.trim());
            const newRegistry = { ...commissionRegistry };
            let processedCount = 0;

            // Map Column Names to Levels
            const levelMap: Record<string, string> = {
                'FA': '70',
                'SFA': '85',
                'SM': '100',
                'SM II': '107.5',
                'ED/SM III': '115',
                'ED (B1)/SED+          SM III (B1)': '120', // Exact match from CSV provided
                'ED (B1)/SED+ SM III (B1)': '120', // Potential trimmed match
                'ED+ (B2)             SM III  (B2)': '125',
                'ED+ (B2) SM III  (B2)': '125',
                'ED+ (B3)              SM III  (B3)': '130',
                'ED+ (B3) SM III  (B3)': '130',
                'RANDY SPECIAL': '138'
            };

            // Also support simple index based mapping if column names vary slightly but position is constant?
            // Safer to rely on finding the column index for each key.
            const colIndices: Record<string, number> = {};
            headers.forEach((h, i) => {
                // Fuzzy match for complex headers
                if (h.includes('ED (B1)')) colIndices['120'] = i;
                else if (h.includes('ED+ (B2)')) colIndices['125'] = i;
                else if (h.includes('ED+ (B3)')) colIndices['130'] = i;
                else if (levelMap[h]) colIndices[levelMap[h]] = i;
            });

            // Iterate Data Rows
            for (let i = headerRowIndex + 1; i < rows.length; i++) {
                const cols = rows[i].split(',');
                if (cols.length < 5) continue; // Skip empty rows

                const carrier = cols[0]?.trim(); // "Company" is usually col 0
                const product = cols[1]?.trim();
                const type = cols[2]?.trim(); // "Type"
                const compYear = cols[3]?.trim(); // "Comp Year"

                if (!carrier || !product) continue;

                // Initialize nested objects if missing
                if (!newRegistry[carrier]) newRegistry[carrier] = {};
                if (!newRegistry[carrier][product]) newRegistry[carrier][product] = {};

                // Determine if this row is FYC or Renewal
                const isFYC = compYear.toLowerCase().includes('1st year');
                const isRenewal = compYear.toLowerCase().includes('renewal') || compYear.toLowerCase().includes('years 2');
                const isExcess = compYear.toLowerCase().includes('excess');

                // Iterate through known level columns
                Object.entries(colIndices).forEach(([level, colIdx]) => {
                    const rateStr = cols[colIdx];
                    if (!rateStr) return;

                    const rate = parsePercentage(rateStr);

                    // Ensure level object exists
                    if (!newRegistry[carrier][product][level]) {
                        newRegistry[carrier][product][level] = { fyc: 0, renewals: 0 };
                    }

                    if (isFYC) {
                        newRegistry[carrier][product][level].fyc = rate;
                    } else if (isRenewal) {
                        newRegistry[carrier][product][level].renewals = rate;
                    } else if (isExcess) {
                        newRegistry[carrier][product][level].excess = rate;
                    }
                });
                processedCount++;
            }

            setCommissionRegistry(newRegistry);
            localStorage.setItem('arise_commission_registry', JSON.stringify(newRegistry));
            setUploadStatus(`Success! Processed ${processedCount} rows. Registry Updated.`);
        };
        reader.readAsText(file);
    };

    const handleAdvanceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        // Placeholder for the 2nd file logic
        setUploadStatus('Advance Rules file uploaded (Logic pending implementation).');
    };

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-slate-500">
                <div className="w-8 h-8 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
                <p>Loading Platform Data...</p>
            </div>
        );
    }

    return (
        <div className="animate-fade-in space-y-6 pb-10">
            {/* Header Area */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <Shield className="text-indigo-600" /> Platform Administration
                    </h2>
                    <p className="text-slate-500 text-sm">Super Admin Console • Managing {users.length.toLocaleString()} total users</p>
                </div>

                {/* Tab Switcher */}
                <div className="flex bg-white p-1 rounded-lg border border-gray-200 shadow-sm">
                    <button
                        onClick={() => setActiveTab('USERS')}
                        className={`px-4 py-2 text-sm font-bold rounded-md transition-all flex items-center gap-2 ${
                            activeTab === 'USERS' 
                                ? 'bg-indigo-600 text-white shadow-sm' 
                                : 'text-slate-500 hover:bg-gray-50'
                        }`}
                    >
                        <Users size={16} /> User Management
                    </button>
                    <button
                        onClick={() => setActiveTab('COMMISSIONS')}
                        className={`px-4 py-2 text-sm font-bold rounded-md transition-all flex items-center gap-2 ${
                            activeTab === 'COMMISSIONS' 
                                ? 'bg-indigo-600 text-white shadow-sm' 
                                : 'text-slate-500 hover:bg-gray-50'
                        }`}
                    >
                        <Calculator size={16} /> Carrier Products & Comp
                    </button>
                </div>
            </div>

            {/* TAB CONTENT */}
            {activeTab === 'USERS' ? (
                <>
                    {/* Payment Failure Alert Banner */}
                    {stats.pastDueUsers > 0 && (
                        <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-r-xl shadow-sm flex flex-col md:flex-row justify-between items-center gap-4 animate-fade-in">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-red-100 rounded-full text-red-600">
                                    <AlertTriangle size={20} />
                                </div>
                                <div>
                                    <h3 className="font-bold text-red-900">Payment Failures Detected</h3>
                                    <p className="text-sm text-red-700">
                                        There are <span className="font-bold">{stats.pastDueUsers}</span> accounts with failed payments this cycle. Immediate action required.
                                    </p>
                                </div>
                            </div>
                            <button 
                                onClick={() => applyQuickFilter('past_due')}
                                className="px-4 py-2 bg-white border border-red-200 text-red-700 font-bold text-sm rounded-lg hover:bg-red-100 transition-colors flex items-center gap-2 whitespace-nowrap shadow-sm"
                            >
                                Review Failed Accounts <ArrowRight size={16} />
                            </button>
                        </div>
