import { CommissionRegistry, CommissionRule } from '../types';

export const getCommissionRegistry = (): CommissionRegistry => {
    try {
        const saved = localStorage.getItem('arise_commission_registry');
        return saved ? JSON.parse(saved) : {};
    } catch {
        return {};
    }
};

export const getAvailableCarriers = (): string[] => {
    const registry = getCommissionRegistry();
    return Object.keys(registry).sort();
};

export const getAvailableProducts = (carrier: string): string[] => {
    const registry = getCommissionRegistry();
    if (!registry[carrier]) return [];
    return Object.keys(registry[carrier]).sort();
};

/**
 * Calculates the exact commission based on the uploaded matrix.
 * @param carrier Name of the carrier (e.g. Aetna)
 * @param product Name of the product (e.g. Final Expense)
 * @param premium Annual premium amount
 * @param compLevel Agent's compensation level (e.g. 100, 110, 120)
 * @returns Object containing calculated values
 */
export const calculateCommissionExact = (
    carrier: string, 
    product: string, 
    premium: number, 
    compLevel: number
): { total: number, fycRate: number } => {

    // Default Fallback
    const fallback = {
        total: premium * (compLevel / 100),
        fycRate: compLevel / 100
    };

    if (!carrier || !product) return fallback;

    const registry = getCommissionRegistry();

    // 1. Find Carrier (Case insensitive search)
    const carrierKey = Object.keys(registry).find(k => k.toLowerCase() === carrier.toLowerCase());
    if (!carrierKey) return fallback;

    // 2. Find Product (Case insensitive search)
    const productData = registry[carrierKey];
    const productKey = Object.keys(productData).find(k => k.toLowerCase() === product.toLowerCase());
    if (!productKey) return fallback;

    const levelsData = productData[productKey];

    // 3. Find Exact Level
    // The registry keys are strings like "70", "80", "100"
    // We try to find exact match.
    const levelKey = compLevel.toString();
    const rule = levelsData[levelKey];

    if (rule) {
        return {
            total: premium * rule.fyc,
            fycRate: rule.fyc
        };
    }

    // 4. If exact match not found, find nearest lower level (Safety)
    // E.g. Agent is 95, but grid has 90 and 100. Use 90.
    const sortedLevels = Object.keys(levelsData)
        .map(Number)
        .sort((a, b) => b - a); // Descending

    const nearestLevel = sortedLevels.find(lvl => lvl <= compLevel);

    if (nearestLevel) {
        const nearestRule = levelsData[nearestLevel.toString()];
        return {
            total: premium * nearestRule.fyc,
            fycRate: nearestRule.fyc
        };
    }

    return fallback;
};

import React, { useState, useEffect } from 'react';
import { MOCK_TEAM } from '../services/mockData';
import { User, ChevronRight, TrendingUp, Settings, Save, X, Briefcase, ChevronDown, ChevronUp } from 'lucide-react';
import { UserProfile, TeamMember } from '../types';
