                                            </div>
                                            <button onClick={() => setExpandedMemberId(null)} className="text-gray-400 hover:text-gray-600">
                                                <X size={20} />
                                            </button>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
