                                            ) : availableCarriers.map(carrier => {
                                                const currentLevel = editingMember.carrierCompLevels?.[carrier] || member.defaultCompLevel;
                                                const isOverridden = editingMember.carrierCompLevels?.[carrier] !== undefined;

                                                return (
