                <p>Loading Platform Data...</p>
            </div>
        );
    }

    return (
        <div className="animate-fade-in space-y-6 pb-10">
            {/* Header Area */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <Shield className="text-indigo-600" /> Platform Administration
                    </h2>
                    <p className="text-slate-500 text-sm">Super Admin Console • Managing {users.length.toLocaleString()} total users</p>
                </div>

                {/* Tab Switcher */}
                <div className="flex bg-white p-1 rounded-lg border border-gray-200 shadow-sm">
                    <button
                        onClick={() => setActiveTab('USERS')}
                        className={`px-4 py-2 text-sm font-bold rounded-md transition-all flex items-center gap-2 ${
                            activeTab === 'USERS' 
                                ? 'bg-indigo-600 text-white shadow-sm' 
                                : 'text-slate-500 hover:bg-gray-50'
                        }`}
                    >
                        <Users size={16} /> User Management
                    </button>
                    <button
                        onClick={() => setActiveTab('COMMISSIONS')}
                        className={`px-4 py-2 text-sm font-bold rounded-md transition-all flex items-center gap-2 ${
                            activeTab === 'COMMISSIONS' 
                                ? 'bg-indigo-600 text-white shadow-sm' 
                                : 'text-slate-500 hover:bg-gray-50'
                        }`}
                    >
                        <Calculator size={16} /> Carrier Products & Comp
                    </button>
                </div>
            </div>

            {/* TAB CONTENT */}
            {activeTab === 'USERS' ? (
                <>
                    {/* Payment Failure Alert Banner */}
                    {stats.pastDueUsers > 0 && (
