                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Email</label>
                        <input 
                            type="email" 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={editingClient.email}
                            onChange={(e) => setEditingClient({...editingClient, email: e.target.value})}
                        />
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Address / State</label>
                        <div className="relative">
                            <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg pl-8 pr-2 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.address}
                                onChange={(e) => setEditingClient({...editingClient, address: e.target.value})}
                                placeholder="123 Main St, State, Zip"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Lead Type</label>
                            <select 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.leadType || 'FEX'}
                                onChange={(e) => setEditingClient({...editingClient, leadType: e.target.value as any})}
                            >
                                <option value="FEX">Final Expense</option>
                                <option value="MP">Mortgage Protection</option>
                                <option value="IUL">IUL / Wealth</option>
                                <option value="VET">Veteran</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Stage</label>
                            <select 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={editingClient.pipelineStage}
                                onChange={(e) => setEditingClient({...editingClient, pipelineStage: e.target.value as PipelineStage})}
                            >
                                {stages.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Notes</label>
                        <textarea 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none bg-white text-slate-900"
                            rows={3}
                            value={editingClient.notes}
                            onChange={(e) => setEditingClient({...editingClient, notes: e.target.value})}
                        />
                    </div>

                    <div className="pt-2 flex gap-3">
                        <button 
                            onClick={() => setIsEditModalOpen(false)}
                            className="flex-1 py-2.5 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={handleSaveEdit}
                            className="flex-1 py-2.5 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2"
                        >
                            <Save size={16} /> Save Changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

import React, { useState, useRef, useEffect } from 'react';
import { PipelineStage, Client } from '../types';
import { MoreHorizontal, Plus, Calendar as CalendarIcon, X, ChevronRight, ChevronLeft, Phone, MapPin, Edit2, Save, Cake, GripVertical, Upload, ArrowRight, FileSpreadsheet, CheckCircle2, Filter, BookOpen, Clock, Tag } from 'lucide-react';
import { ScriptLibrary } from './ScriptLibrary';

interface PipelineProps {
    clients: Client[];
    currentUserId: string; // ID of the logged-in agent
    onUpdateClients: (clients: Client[]) => void;
}

type LeadType = 'FEX' | 'MP' | 'IUL' | 'VET' | 'ALL';

const Pipeline: React.FC<PipelineProps> = ({ clients, currentUserId, onUpdateClients }) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isScriptsOpen, setIsScriptsOpen] = useState(false);

  // Appointment Modal State
  const [isApptModalOpen, setIsApptModalOpen] = useState(false);
  const [pendingMove, setPendingMove] = useState<{ clientId: string; stage: PipelineStage } | null>(null);
  const [apptDetails, setApptDetails] = useState({
      date: new Date().toISOString().split('T')[0],
      time: '10:00',
      notes: ''
  });

  // Filter State
  const [activeFilter, setActiveFilter] = useState<LeadType>('ALL');
  const [isFilterDropdownOpen, setIsFilterDropdownOpen] = useState(false);

  // Import Modal State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importStep, setImportStep] = useState<'UPLOAD' | 'MAP'>('UPLOAD');
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<Record<string, string>[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      stage: ''
  });

  const [newLead, setNewLead] = useState<{
      firstName: string;
      lastName: string;
      email: string;
      phone: string;
      dob: string;
      state: string;
      stage: PipelineStage;
      leadType: Client['leadType'];
  }>({ 
      firstName: '', 
      lastName: '', 
      email: '', 
      phone: '', 
      dob: '', 
      state: '', 
      stage: PipelineStage.NEW_LEAD,
      leadType: 'FEX' // Default
  });

  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Drag and Drop State
  const [draggedClientId, setDraggedClientId] = useState<string | null>(null);
  const [targetStage, setTargetStage] = useState<PipelineStage | null>(null);

  // Auto-scroll Refs
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const autoScrollSpeed = useRef<number>(0);
  const animationFrameId = useRef<number | null>(null);

  const stages = Object.values(PipelineStage);

  // Clean up auto-scroll on unmount
  useEffect(() => {
      return () => stopAutoScroll();
  }, []);

  const getClientsByStage = (stage: PipelineStage) => {
    return clients.filter(c => 
        c.pipelineStage === stage && 
        (activeFilter === 'ALL' || c.leadType === activeFilter)
    );
  };

  const moveStage = (clientId: string, direction: 'next' | 'prev') => {
    const client = clients.find(c => c.id === clientId);
    if (!client) return;

    const currentIndex = stages.indexOf(client.pipelineStage);
    let newIndex = currentIndex;

    if (direction === 'next' && currentIndex < stages.length - 1) {
      newIndex++;
    } else if (direction === 'prev' && currentIndex > 0) {
      newIndex--;
    }

    const nextStage = stages[newIndex];

    // If moving TO Appointment Set, trigger modal
    if (nextStage === PipelineStage.APPOINTMENT_SET && client.pipelineStage !== PipelineStage.APPOINTMENT_SET) {
        setPendingMove({ clientId, stage: nextStage });
        setApptDetails({ date: new Date().toISOString().split('T')[0], time: '10:00', notes: '' });
        setIsApptModalOpen(true);
        return;
    }

    onUpdateClients(clients.map(c => 
        c.id === clientId ? { ...c, pipelineStage: nextStage } : c
    ));
  };

  const handleConfirmAppointment = () => {
      if (!pendingMove) return;

      const client = clients.find(c => c.id === pendingMove.clientId);
      if (client) {
          // 1. Save to LocalStorage for Calendar component
          try {
              const savedEvents = localStorage.getItem('arise_calendar_events');
              const events = savedEvents ? JSON.parse(savedEvents) : [];

              // Dynamic Title Construction
              const leadTypeLabel = client.leadType || 'General';
              const eventTitle = `${leadTypeLabel} Appt: ${client.firstName} ${client.lastName}`;

              events.push({
                  id: `evt-${Date.now()}`,
                  title: eventTitle,
                  date: apptDetails.date,
                  time: apptDetails.time,
                  type: 'Meeting'
              });

              localStorage.setItem('arise_calendar_events', JSON.stringify(events));
          } catch (e) {
              console.error("Failed to sync to calendar", e);
          }

          // 2. Update Client Stage
          onUpdateClients(clients.map(c => 
              c.id === pendingMove.clientId 
                  ? { ...c, pipelineStage: pendingMove.stage } 
                  : c
          ));
      }

      setIsApptModalOpen(false);
      setPendingMove(null);
  };

  const handleAddLead = () => {
    if (!newLead.firstName || !newLead.lastName) return;

    const lead: Client = {
        id: Date.now().toString(),
        agentId: currentUserId,
        firstName: newLead.firstName,
        lastName: newLead.lastName,
        email: newLead.email,
        phone: newLead.phone,
        address: newLead.state, // Simple mapping for now
        dateOfBirth: newLead.dob,
        policies: [],
        notes: 'New lead added manually',
        pipelineStage: newLead.stage,
        leadSource: 'Manual',
        leadType: newLead.leadType,
        lastContactDate: new Date().toISOString().split('T')[0]
    };

    onUpdateClients([...clients, lead]);
    setIsAddModalOpen(false);
    setNewLead({ 
        firstName: '', 
        lastName: '', 
        email: '', 
        phone: '', 
        dob: '', 
        state: '', 
        stage: PipelineStage.NEW_LEAD,
        leadType: 'FEX' 
    });
  };

  const openEditModal = (client: Client) => {
      setEditingClient({ ...client });
      setIsEditModalOpen(true);
  };

  const handleSaveEdit = () => {
      if (!editingClient) return;
      onUpdateClients(clients.map(c => c.id === editingClient.id ? editingClient : c));
      setIsEditModalOpen(false);
      setEditingClient(null);
  };

  // --- Auto Scroll Logic ---

  const startAutoScroll = () => {
      if (animationFrameId.current) return;

      const scroll = () => {
          if (scrollContainerRef.current && autoScrollSpeed.current !== 0) {
              scrollContainerRef.current.scrollLeft += autoScrollSpeed.current;
              animationFrameId.current = requestAnimationFrame(scroll);
          } else {
              stopAutoScroll();
          }
      };
      animationFrameId.current = requestAnimationFrame(scroll);
  };

  const stopAutoScroll = () => {
      if (animationFrameId.current) {
          cancelAnimationFrame(animationFrameId.current);
          animationFrameId.current = null;
      }
      autoScrollSpeed.current = 0;
  };

  const handleContainerDragOver = (e: React.DragEvent) => {
      // Allow drop events to bubble up properly
      e.preventDefault(); 

      if (!draggedClientId || !scrollContainerRef.current) return;

      const { left, right } = scrollContainerRef.current.getBoundingClientRect();
      const x = e.clientX;
      const threshold = 150; // Distance from edge to trigger scroll
      const maxSpeed = 15;

      if (x < left + threshold) {
          // Scroll Left
          const intensity = 1 - ((x - left) / threshold);
          autoScrollSpeed.current = -1 * maxSpeed * intensity;
          startAutoScroll();
      } else if (x > right - threshold) {
          // Scroll Right
          const intensity = 1 - ((right - x) / threshold);
          autoScrollSpeed.current = maxSpeed * intensity;
          startAutoScroll();
      } else {
          // In the safe zone
          autoScrollSpeed.current = 0;
      }
  };

  // --- Drag and Drop Handlers ---

  const handleDragStart = (e: React.DragEvent, clientId: string) => {
      setDraggedClientId(clientId);
      e.dataTransfer.setData('clientId', clientId);
      e.dataTransfer.effectAllowed = 'move';

      // Create a ghost image if needed, or rely on browser default
  };

  const handleDragEnd = () => {
      setDraggedClientId(null);
      setTargetStage(null);
      stopAutoScroll();
  };

  const handleDragOver = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault(); // Necessary to allow dropping
      // Note: We don't stop propagation so container can see drag position for scrolling
      if (targetStage !== stage) {
          setTargetStage(stage);
      }
  };

  const handleDrop = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault();
      const clientId = e.dataTransfer.getData('clientId');

      if (clientId) {
          // If dropping into APPOINTMENT_SET, trigger modal first
          if (stage === PipelineStage.APPOINTMENT_SET) {
              setPendingMove({ clientId, stage });
              setApptDetails({ date: new Date().toISOString().split('T')[0], time: '10:00', notes: '' });
              setIsApptModalOpen(true);
          } else {
              onUpdateClients(clients.map(client => {
                  if (client.id === clientId) {
                      return { ...client, pipelineStage: stage };
                  }
                  return client;
              }));
          }
      }

      handleDragEnd(); // Cleanup
  };

  // --- Import Handlers ---

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const text = evt.target?.result as string;
            // Basic CSV parse
            const lines = text.split(/\r\n|\n/).filter(line => line.trim() !== '');
            if (lines.length > 0) {
                const headers = lines[0].split(',').map(h => h.trim());
                setCsvHeaders(headers);

                const data = lines.slice(1).map(line => {
                    const values = line.split(',');
                    const row: Record<string, string> = {};
                    headers.forEach((h, i) => {
                        row[h] = values[i]?.trim() || '';
                    });
                    return row;
                });
                setCsvData(data);
                setImportStep('MAP');

                // Auto-guess mapping
                const newMapping = { ...fieldMapping };
                headers.forEach(h => {
                    const lowerH = h.toLowerCase();
                    if (lowerH.includes('first')) newMapping.firstName = h;
                    else if (lowerH.includes('last')) newMapping.lastName = h;
                    else if (lowerH.includes('email')) newMapping.email = h;
                    else if (lowerH.includes('phone')) newMapping.phone = h;
                    else if (lowerH.includes('stage') || lowerH.includes('status')) newMapping.stage = h;
                });
                setFieldMapping(newMapping);
            }
        };
        reader.readAsText(file);
    }
  };

  const executeImport = () => {
    const newClients = csvData.map(row => ({
        id: `imported-${Date.now()}-${Math.random()}`,
        agentId: currentUserId,
        firstName: row[fieldMapping.firstName] || 'Unknown',
        lastName: row[fieldMapping.lastName] || 'Client',
        email: row[fieldMapping.email] || '',
        phone: row[fieldMapping.phone] || '',
        address: '',
        policies: [],
        notes: 'Imported via CSV',
        pipelineStage: (row[fieldMapping.stage] as PipelineStage) || PipelineStage.NEW_LEAD,
        leadSource: 'Import',
        lastContactDate: new Date().toISOString().split('T')[0]
    }));

    onUpdateClients([...clients, ...newClients]);
    setIsImportModalOpen(false);
    setImportStep('UPLOAD');
    setCsvData([]);
    setCsvHeaders([]);
  };

  return (
    <div className="h-full flex flex-col animate-fade-in relative">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-slate-800">Leads Pipeline</h2>
            <div className="relative">
                <button 
                    onClick={() => setIsFilterDropdownOpen(!isFilterDropdownOpen)}
                    className={`px-3 py-1.5 text-xs font-bold rounded-full flex items-center gap-1 border transition-colors ${
                        activeFilter === 'ALL' 
                            ? 'bg-white border-gray-300 text-gray-600 hover:bg-gray-50' 
                            : 'bg-indigo-100 border-indigo-200 text-indigo-700'
                    }`}
                >
                    <Filter size={12} /> 
                    {activeFilter === 'ALL' ? 'All Types' : activeFilter === 'FEX' ? 'Final Expense' : activeFilter === 'MP' ? 'Mortgage Prot.' : activeFilter === 'IUL' ? 'IUL / Wealth' : 'Veterans'}
                </button>
                {isFilterDropdownOpen && (
                    <div className="absolute top-full left-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-gray-100 z-20 py-1">
                        <button 
                            onClick={() => { setActiveFilter('ALL'); setIsFilterDropdownOpen(false); }}
                            className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700"
                        >
                            All Leads
                        </button>
                        <div className="border-t border-gray-100 my-1"></div>
                        <button onClick={() => { setActiveFilter('FEX'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Final Expense</button>
                        <button onClick={() => { setActiveFilter('MP'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Mortgage Protection</button>
                        <button onClick={() => { setActiveFilter('IUL'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">IUL / Wealth</button>
                        <button onClick={() => { setActiveFilter('VET'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Veteran Leads</button>
                    </div>
                )}
            </div>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setIsScriptsOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-50 border border-indigo-100 text-indigo-700 rounded-lg hover:bg-indigo-100 text-sm font-bold transition-colors"
            >
                <BookOpen size={16} /> Quick Scripts
            </button>
            <button 
                onClick={() => setIsImportModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors"
            >
                <Upload size={16} /> Import
            </button>
            <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
            >
                <Plus size={16} /> Add Lead
            </button>
        </div>
      </div>

      <div 
        className="flex-1 overflow-x-auto pb-4" 
        ref={scrollContainerRef}
        onDragOver={handleContainerDragOver}
      >
        <div className="flex gap-4 h-full min-w-max">
          {stages.map((stage) => {
            const stageClients = getClientsByStage(stage);
            const isDragTarget = targetStage === stage && draggedClientId !== null;
            const isNegativeStage = stage === PipelineStage.NOT_INTERESTED || stage === PipelineStage.BAD_NUMBER;

            return (
              <div 
                key={stage} 
                className={`w-80 flex flex-col rounded-xl border transition-all duration-200 h-full ${
                    isDragTarget 
                        ? 'bg-indigo-50 border-indigo-300 ring-2 ring-indigo-200 shadow-lg scale-[1.01]' 
                        : isNegativeStage ? 'bg-gray-100/50 border-gray-200' : 'bg-gray-50/50 border-gray-100'
                }`}
                onDragOver={(e) => handleDragOver(e, stage)}
                onDrop={(e) => handleDrop(e, stage)}
              >
                {/* Stage Header */}
                <div className={`p-4 border-b rounded-t-xl backdrop-blur-sm transition-colors ${
                    isDragTarget ? 'bg-indigo-100/50 border-indigo-200' : isNegativeStage ? 'bg-gray-200/50 border-gray-200' : 'border-gray-100 bg-white/50'
                }`}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className={`font-semibold ${isDragTarget ? 'text-indigo-800' : isNegativeStage ? 'text-gray-600' : 'text-slate-700'}`}>{stage}</h3>
                    <MoreHorizontal size={16} className="text-gray-400 cursor-pointer" />
                  </div>
                  <div className="flex justify-between items-center text-xs text-gray-500">
                    <span>{stageClients.length} Leads</span>
                  </div>
                </div>

                {/* Cards */}
                <div className="p-3 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                  {stageClients.map((client) => (
                    <div 
                        key={client.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, client.id)}
                        onDragEnd={handleDragEnd}
                        className={`bg-white p-4 rounded-lg shadow-sm border border-gray-100 hover:shadow-md transition-all group relative cursor-grab active:cursor-grabbing ${
                            draggedClientId === client.id ? 'opacity-40 border-dashed border-indigo-300' : ''
                        }`}
                    >
                      {/* Grip Icon for affordance */}
                      <div className="absolute top-1/2 left-1 -translate-y-1/2 opacity-0 group-hover:opacity-30 transition-opacity">
                          <GripVertical size={16} />
                      </div>

                      {/* Name and Source */}
                      <div className="flex justify-between items-start mb-2 pl-2">
                         <span className="font-bold text-slate-800 text-sm truncate max-w-[140px] block" title={`${client.firstName} ${client.lastName}`}>
                            {client.firstName} {client.lastName}
                         </span>
                         {/* Badge Removed to avoid redundancy with the new row, but keeping it if user wants at a glance. Actually, let's keep it as a colored pill for quick scanning. */}
                         {client.leadType && (
                             <span className={`text-[10px] uppercase tracking-wider font-bold px-1.5 py-0.5 rounded border 
                                ${client.leadType === 'FEX' ? 'bg-rose-50 text-rose-600 border-rose-100' : 
                                  client.leadType === 'MP' ? 'bg-blue-50 text-blue-600 border-blue-100' : 
                                  client.leadType === 'IUL' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                  'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>
                                 {client.leadType}
                             </span>
                         )}
                      </div>

                      {/* Contact Details */}
                      <div className="space-y-2 mt-3 pl-2">
                          <div className="flex items-center text-xs text-gray-500">
                              <Tag size={12} className="mr-2 text-slate-400" />
                              <span className="font-medium text-slate-700">{client.leadType || 'General Lead'}</span>
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Phone size={12} className="mr-2 text-slate-400" />
                              {client.phone ? client.phone : <span className="italic text-gray-400">No phone</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Cake size={12} className="mr-2 text-slate-400" />
                              {client.dateOfBirth ? client.dateOfBirth : <span className="italic text-gray-400">No DOB</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <MapPin size={12} className="mr-2 text-slate-400" />
                              {client.address ? <span className="truncate max-w-[180px]">{client.address}</span> : <span className="italic text-gray-400">No State/Address</span>}
                          </div>

                          {/* Last Contact Footer */}
                          <div className="flex items-center text-xs text-slate-400 pt-2 border-t border-gray-50 mt-2">
                              <CalendarIcon size={12} className="mr-2 opacity-70" />
                              Last Contact: {client.lastContactDate}
                          </div>
                      </div>

                      {/* Action Buttons Overlay (Still available if preferred over drag) */}
                      <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 rounded-lg border border-indigo-100 z-10 pointer-events-none">
                          <div className="flex items-center gap-2 pointer-events-auto">
                              <button 
                                onClick={() => moveStage(client.id, 'prev')}
                                disabled={stage === PipelineStage.NEW_LEAD}
                                className="p-2 rounded-full bg-gray-100 hover:bg-gray-200 disabled:opacity-30 text-gray-600 border border-gray-200"
                                title="Move Back"
                              >
                                 <ChevronLeft size={16} />
                              </button>

                              <button 
                                 onClick={() => openEditModal(client)}
                                 className="flex items-center gap-1 px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-lg shadow-md hover:bg-indigo-700 transition-colors"
                              >
                                 <Edit2 size={12} /> Edit Lead
                              </button>

                              <button 
                                 onClick={() => moveStage(client.id, 'next')}
                                 disabled={stage === PipelineStage.BAD_NUMBER}
                                 className="p-2 rounded-full bg-indigo-50 hover:bg-indigo-100 disabled:opacity-30 text-indigo-600 border border-indigo-100"
                                 title="Move Next"
                              >
