import React, { useState, useRef, useEffect } from 'react';
import { PipelineStage, Client, Policy, PolicyType, PolicyStatus } from '../types';
import { MoreHorizontal, Plus, Calendar as CalendarIcon, X, ChevronRight, ChevronLeft, Phone, MapPin, Edit2, Save, Cake, GripVertical, Upload, ArrowRight, FileSpreadsheet, CheckCircle2, Filter, BookOpen, Clock, Tag, ShieldCheck, DollarSign } from 'lucide-react';
import { ScriptLibrary } from './ScriptLibrary';
import { getAvailableCarriers, getAvailableProducts } from '../services/commissionService';

interface PipelineProps {
    clients: Client[];
    currentUserId: string; // ID of the logged-in agent
    onUpdateClients: (clients: Client[]) => void;
}

type LeadType = 'FEX' | 'MP' | 'IUL' | 'VET' | 'ALL';

const Pipeline: React.FC<PipelineProps> = ({ clients, currentUserId, onUpdateClients }) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isScriptsOpen, setIsScriptsOpen] = useState(false);

  // Appointment Modal State
  const [isApptModalOpen, setIsApptModalOpen] = useState(false);
  const [pendingMove, setPendingMove] = useState<{ clientId: string; stage: PipelineStage } | null>(null);
  const [apptDetails, setApptDetails] = useState({
      date: new Date().toISOString().split('T')[0],
      time: '10:00',
      notes: ''
  });

  // Policy Capture Modal State (App Approved / Underwriting)
  const [isPolicyModalOpen, setIsPolicyModalOpen] = useState(false);
  const [pendingPolicyMove, setPendingPolicyMove] = useState<{ clientId: string; stage: PipelineStage } | null>(null);
  const [policyForm, setPolicyForm] = useState<{
      carrier: string;
      policyType: PolicyType;
      productName: string;
      policyNumber: string;
      premium: string;
      coverageAmount: string;
      startDate: string;
  }>({
      carrier: '',
      policyType: PolicyType.TERM,
      productName: '',
      policyNumber: '',
      premium: '',
      coverageAmount: '',
      startDate: new Date().toISOString().split('T')[0]
  });
  const [carrierOptions, setCarrierOptions] = useState<string[]>([]);
  const [productOptions, setProductOptions] = useState<string[]>([]);

  // Load carrier options
  useEffect(() => {
      setCarrierOptions(getAvailableCarriers());
  }, []);

  // Update product options when carrier changes
  useEffect(() => {
      if (policyForm.carrier) {
          setProductOptions(getAvailableProducts(policyForm.carrier));
      } else {
          setProductOptions([]);
      }
  }, [policyForm.carrier]);

  // Filter State
  const [activeFilter, setActiveFilter] = useState<LeadType>('ALL');
  const [isFilterDropdownOpen, setIsFilterDropdownOpen] = useState(false);

  // Import Modal State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importStep, setImportStep] = useState<'UPLOAD' | 'MAP'>('UPLOAD');
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<Record<string, string>[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      stage: ''
  });

  const [newLead, setNewLead] = useState<{
      firstName: string;
      lastName: string;
      email: string;
      phone: string;
      dob: string;
      state: string;
      stage: PipelineStage;
      leadType: Client['leadType'];
  }>({ 
      firstName: '', 
      lastName: '', 
      email: '', 
      phone: '', 
      dob: '', 
      state: '', 
      stage: PipelineStage.NEW_LEAD,
      leadType: 'FEX' // Default
  });

  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Drag and Drop State
  const [draggedClientId, setDraggedClientId] = useState<string | null>(null);
  const [targetStage, setTargetStage] = useState<PipelineStage | null>(null);

  // Auto-scroll Refs
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const autoScrollSpeed = useRef<number>(0);
  const animationFrameId = useRef<number | null>(null);

  const stages = Object.values(PipelineStage);

  // Clean up auto-scroll on unmount
  useEffect(() => {
      return () => stopAutoScroll();
  }, []);

  const getClientsByStage = (stage: PipelineStage) => {
    return clients.filter(c => 
        c.pipelineStage === stage && 
        (activeFilter === 'ALL' || c.leadType === activeFilter)
    );
  };

  const initiateStageMove = (clientId: string, stage: PipelineStage) => {
      // 1. Intercept APPOINTMENT_SET
      if (stage === PipelineStage.APPOINTMENT_SET) {
          setPendingMove({ clientId, stage });
          setApptDetails({ date: new Date().toISOString().split('T')[0], time: '10:00', notes: '' });
          setIsApptModalOpen(true);
          return;
      }

      // 2. Intercept APPLICATION_APPROVED or UNDERWRITING
      if (stage === PipelineStage.APPLICATION_TAKEN || stage === PipelineStage.UNDERWRITING) {
          const client = clients.find(c => c.id === clientId);
          // Only show modal if they don't already have a policy or if we want to add a new one?
          // For pipeline flow, we assume moving to this stage implies a new app.
          setPendingPolicyMove({ clientId, stage });
          setPolicyForm({
              carrier: '',
              policyType: PolicyType.TERM,
              productName: '',
              policyNumber: '',
              premium: '',
              coverageAmount: '',
              startDate: new Date().toISOString().split('T')[0]
          });
          setIsPolicyModalOpen(true);
          return;
      }

      // 3. Normal Move
      onUpdateClients(clients.map(c => 
          c.id === clientId ? { ...c, pipelineStage: stage } : c
      ));
  };

  const moveStage = (clientId: string, direction: 'next' | 'prev') => {
    const client = clients.find(c => c.id === clientId);
    if (!client) return;

    const currentIndex = stages.indexOf(client.pipelineStage);
    let newIndex = currentIndex;

    if (direction === 'next' && currentIndex < stages.length - 1) {
      newIndex++;
    } else if (direction === 'prev' && currentIndex > 0) {
      newIndex--;
    }

    const nextStage = stages[newIndex];
    if (nextStage !== client.pipelineStage) {
        initiateStageMove(clientId, nextStage);
    }
  };

  const handleConfirmAppointment = () => {
      if (!pendingMove) return;

      const client = clients.find(c => c.id === pendingMove.clientId);
      if (client) {
          // 1. Save to LocalStorage for Calendar component
          try {
              const savedEvents = localStorage.getItem('arise_calendar_events');
              const events = savedEvents ? JSON.parse(savedEvents) : [];

              // Dynamic Title Construction
              const leadTypeLabel = client.leadType || 'General';
              const eventTitle = `${leadTypeLabel} Appt: ${client.firstName} ${client.lastName}`;

              events.push({
                  id: `evt-${Date.now()}`,
                  title: eventTitle,
                  date: apptDetails.date,
                  time: apptDetails.time,
                  type: 'Meeting'
              });

              localStorage.setItem('arise_calendar_events', JSON.stringify(events));
          } catch (e) {
              console.error("Failed to sync to calendar", e);
          }

          // 2. Update Client Stage
          onUpdateClients(clients.map(c => 
              c.id === pendingMove.clientId 
                  ? { ...c, pipelineStage: pendingMove.stage } 
                  : c
          ));
      }

      setIsApptModalOpen(false);
      setPendingMove(null);
  };

  const handleSavePolicyMove = () => {
      if (!pendingPolicyMove) return;
      const client = clients.find(c => c.id === pendingPolicyMove.clientId);
      if (!client) return;

      // 1. Create Policy Object
      const newPolicy: Policy = {
          id: `pol-${Date.now()}`,
          type: policyForm.policyType,
          carrier: policyForm.carrier || 'Pending Carrier',
          productName: policyForm.productName || 'Pending Product',
          policyNumber: policyForm.policyNumber || 'PENDING',
          premium: parseFloat(policyForm.premium) || 0,
          coverageAmount: parseFloat(policyForm.coverageAmount) || 0,
          commission: (parseFloat(policyForm.premium) || 0) * 0.9, // Auto-calc estimate
          startDate: policyForm.startDate,
          endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 20)).toISOString().split('T')[0], // Default 20y
          status: PolicyStatus.PENDING, // Default to Pending until issued
          isPaidOut: false
      };

      // 2. Update Client (Add Policy & Change Stage)
      onUpdateClients(clients.map(c => 
          c.id === pendingPolicyMove.clientId 
              ? { 
                  ...c, 
                  pipelineStage: pendingPolicyMove.stage,
                  policies: [newPolicy, ...c.policies] // Prepend new policy
                } 
              : c
      ));

      setIsPolicyModalOpen(false);
      setPendingPolicyMove(null);
  };

  const handleAddLead = () => {
    if (!newLead.firstName || !newLead.lastName) return;

    const lead: Client = {
        id: Date.now().toString(),
        agentId: currentUserId,
        firstName: newLead.firstName,
        lastName: newLead.lastName,
        email: newLead.email,
        phone: newLead.phone,
        address: newLead.state, // Simple mapping for now
        dateOfBirth: newLead.dob,
        policies: [],
        notes: 'New lead added manually',
        pipelineStage: newLead.stage,
        leadSource: 'Manual',
        leadType: newLead.leadType,
        lastContactDate: new Date().toISOString().split('T')[0]
    };

    onUpdateClients([...clients, lead]);
    setIsAddModalOpen(false);
    setNewLead({ 
        firstName: '', 
        lastName: '', 
        email: '', 
        phone: '', 
        dob: '', 
        state: '', 
        stage: PipelineStage.NEW_LEAD,
        leadType: 'FEX' 
    });
  };

  const openEditModal = (client: Client) => {
      setEditingClient({ ...client });
      setIsEditModalOpen(true);
  };

  const handleSaveEdit = () => {
      if (!editingClient) return;
      onUpdateClients(clients.map(c => c.id === editingClient.id ? editingClient : c));
      setIsEditModalOpen(false);
      setEditingClient(null);
  };

  // --- Auto Scroll Logic ---

  const startAutoScroll = () => {
      if (animationFrameId.current) return;

      const scroll = () => {
          if (scrollContainerRef.current && autoScrollSpeed.current !== 0) {
              scrollContainerRef.current.scrollLeft += autoScrollSpeed.current;
              animationFrameId.current = requestAnimationFrame(scroll);
          } else {
              stopAutoScroll();
          }
      };
      animationFrameId.current = requestAnimationFrame(scroll);
  };

  const stopAutoScroll = () => {
      if (animationFrameId.current) {
          cancelAnimationFrame(animationFrameId.current);
          animationFrameId.current = null;
      }
      autoScrollSpeed.current = 0;
  };

  const handleContainerDragOver = (e: React.DragEvent) => {
      // Allow drop events to bubble up properly
      e.preventDefault(); 

      if (!draggedClientId || !scrollContainerRef.current) return;

      const { left, right } = scrollContainerRef.current.getBoundingClientRect();
      const x = e.clientX;
      const threshold = 150; // Distance from edge to trigger scroll
      const maxSpeed = 15;

      if (x < left + threshold) {
          // Scroll Left
          const intensity = 1 - ((x - left) / threshold);
          autoScrollSpeed.current = -1 * maxSpeed * intensity;
          startAutoScroll();
      } else if (x > right - threshold) {
          // Scroll Right
          const intensity = 1 - ((right - x) / threshold);
          autoScrollSpeed.current = maxSpeed * intensity;
          startAutoScroll();
      } else {
          // In the safe zone
          autoScrollSpeed.current = 0;
      }
  };

  // --- Drag and Drop Handlers ---

  const handleDragStart = (e: React.DragEvent, clientId: string) => {
      setDraggedClientId(clientId);
      e.dataTransfer.setData('clientId', clientId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
      setDraggedClientId(null);
      setTargetStage(null);
      stopAutoScroll();
  };

  const handleDragOver = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault(); // Necessary to allow dropping
      if (targetStage !== stage) {
          setTargetStage(stage);
      }
  };

  const handleDrop = (e: React.DragEvent, stage: PipelineStage) => {
      e.preventDefault();
      const clientId = e.dataTransfer.getData('clientId');

      if (clientId) {
          const client = clients.find(c => c.id === clientId);
          if (client && client.pipelineStage !== stage) {
              initiateStageMove(clientId, stage);
          }
      }

      handleDragEnd(); // Cleanup
  };

  // --- Import Handlers ---

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const text = evt.target?.result as string;
            // Basic CSV parse
            const lines = text.split(/\r\n|\n/).filter(line => line.trim() !== '');
            if (lines.length > 0) {
                const headers = lines[0].split(',').map(h => h.trim());
                setCsvHeaders(headers);

                const data = lines.slice(1).map(line => {
                    const values = line.split(',');
                    const row: Record<string, string> = {};
                    headers.forEach((h, i) => {
                        row[h] = values[i]?.trim() || '';
                    });
                    return row;
                });
                setCsvData(data);
                setImportStep('MAP');

                // Auto-guess mapping
                const newMapping = { ...fieldMapping };
                headers.forEach(h => {
                    const lowerH = h.toLowerCase();
                    if (lowerH.includes('first')) newMapping.firstName = h;
                    else if (lowerH.includes('last')) newMapping.lastName = h;
                    else if (lowerH.includes('email')) newMapping.email = h;
                    else if (lowerH.includes('phone')) newMapping.phone = h;
                    else if (lowerH.includes('stage') || lowerH.includes('status')) newMapping.stage = h;
                });
                setFieldMapping(newMapping);
            }
        };
        reader.readAsText(file);
    }
  };

  const executeImport = () => {
    const newClients = csvData.map(row => ({
        id: `imported-${Date.now()}-${Math.random()}`,
        agentId: currentUserId,
        firstName: row[fieldMapping.firstName] || 'Unknown',
        lastName: row[fieldMapping.lastName] || 'Client',
        email: row[fieldMapping.email] || '',
        phone: row[fieldMapping.phone] || '',
        address: '',
        policies: [],
        notes: 'Imported via CSV',
        pipelineStage: (row[fieldMapping.stage] as PipelineStage) || PipelineStage.NEW_LEAD,
        leadSource: 'Import',
        lastContactDate: new Date().toISOString().split('T')[0]
    }));

    onUpdateClients([...clients, ...newClients]);
    setIsImportModalOpen(false);
    setImportStep('UPLOAD');
    setCsvData([]);
    setCsvHeaders([]);
  };

  return (
    <div className="h-full flex flex-col animate-fade-in relative">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-slate-800">Leads Pipeline</h2>
            <div className="relative">
                <button 
                    onClick={() => setIsFilterDropdownOpen(!isFilterDropdownOpen)}
                    className={`px-3 py-1.5 text-xs font-bold rounded-full flex items-center gap-1 border transition-colors ${
                        activeFilter === 'ALL' 
                            ? 'bg-white border-gray-300 text-gray-600 hover:bg-gray-50' 
                            : 'bg-indigo-100 border-indigo-200 text-indigo-700'
                    }`}
                >
                    <Filter size={12} /> 
                    {activeFilter === 'ALL' ? 'All Types' : activeFilter === 'FEX' ? 'Final Expense' : activeFilter === 'MP' ? 'Mortgage Prot.' : activeFilter === 'IUL' ? 'IUL / Wealth' : 'Veterans'}
                </button>
                {isFilterDropdownOpen && (
                    <div className="absolute top-full left-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-gray-100 z-20 py-1">
                        <button 
                            onClick={() => { setActiveFilter('ALL'); setIsFilterDropdownOpen(false); }}
                            className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700"
                        >
                            All Leads
                        </button>
                        <div className="border-t border-gray-100 my-1"></div>
                        <button onClick={() => { setActiveFilter('FEX'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Final Expense</button>
                        <button onClick={() => { setActiveFilter('MP'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Mortgage Protection</button>
                        <button onClick={() => { setActiveFilter('IUL'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">IUL / Wealth</button>
                        <button onClick={() => { setActiveFilter('VET'); setIsFilterDropdownOpen(false); }} className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 text-slate-700">Veteran Leads</button>
                    </div>
                )}
            </div>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setIsScriptsOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-50 border border-indigo-100 text-indigo-700 rounded-lg hover:bg-indigo-100 text-sm font-bold transition-colors"
            >
                <BookOpen size={16} /> Quick Scripts
            </button>
            <button 
                onClick={() => setIsImportModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-slate-600 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors"
            >
                <Upload size={16} /> Import
            </button>
            <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
            >
                <Plus size={16} /> Add Lead
            </button>
        </div>
      </div>

      <div 
        className="flex-1 overflow-x-auto pb-4" 
        ref={scrollContainerRef}
        onDragOver={handleContainerDragOver}
      >
        <div className="flex gap-4 h-full min-w-max">
          {stages.map((stage) => {
            const stageClients = getClientsByStage(stage);
            const isDragTarget = targetStage === stage && draggedClientId !== null;
            const isNegativeStage = stage === PipelineStage.NOT_INTERESTED || stage === PipelineStage.BAD_NUMBER;

            return (
              <div 
                key={stage} 
                className={`w-80 flex flex-col rounded-xl border transition-all duration-200 h-full ${
                    isDragTarget 
                        ? 'bg-indigo-50 border-indigo-300 ring-2 ring-indigo-200 shadow-lg scale-[1.01]' 
                        : isNegativeStage ? 'bg-gray-100/50 border-gray-200' : 'bg-gray-50/50 border-gray-100'
                }`}
                onDragOver={(e) => handleDragOver(e, stage)}
                onDrop={(e) => handleDrop(e, stage)}
              >
                {/* Stage Header */}
                <div className={`p-4 border-b rounded-t-xl backdrop-blur-sm transition-colors ${
                    isDragTarget ? 'bg-indigo-100/50 border-indigo-200' : isNegativeStage ? 'bg-gray-200/50 border-gray-200' : 'border-gray-100 bg-white/50'
                }`}>
                  <div className="flex justify-between items-center mb-1">
                    <h3 className={`font-semibold ${isDragTarget ? 'text-indigo-800' : isNegativeStage ? 'text-gray-600' : 'text-slate-700'}`}>{stage}</h3>
                    <MoreHorizontal size={16} className="text-gray-400 cursor-pointer" />
                  </div>
                  <div className="flex justify-between items-center text-xs text-gray-500">
                    <span>{stageClients.length} Leads</span>
                  </div>
                </div>

                {/* Cards */}
                <div className="p-3 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                  {stageClients.map((client) => (
                    <div 
                        key={client.id} 
                        draggable
                        onDragStart={(e) => handleDragStart(e, client.id)}
                        onDragEnd={handleDragEnd}
                        className={`bg-white p-4 rounded-lg shadow-sm border border-gray-100 hover:shadow-md transition-all group relative cursor-grab active:cursor-grabbing ${
                            draggedClientId === client.id ? 'opacity-40 border-dashed border-indigo-300' : ''
                        }`}
                    >
                      {/* Grip Icon for affordance */}
                      <div className="absolute top-1/2 left-1 -translate-y-1/2 opacity-0 group-hover:opacity-30 transition-opacity">
                          <GripVertical size={16} />
                      </div>

                      {/* Name and Source */}
                      <div className="flex justify-between items-start mb-2 pl-2">
                         <span className="font-bold text-slate-800 text-sm truncate max-w-[140px] block" title={`${client.firstName} ${client.lastName}`}>
                            {client.firstName} {client.lastName}
                         </span>
                         {client.leadType && (
                             <span className={`text-[10px] uppercase tracking-wider font-bold px-1.5 py-0.5 rounded border 
                                ${client.leadType === 'FEX' ? 'bg-rose-50 text-rose-600 border-rose-100' : 
                                  client.leadType === 'MP' ? 'bg-blue-50 text-blue-600 border-blue-100' : 
                                  client.leadType === 'IUL' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                  'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>
                                 {client.leadType}
                             </span>
                         )}
                      </div>

                      {/* Contact Details */}
                      <div className="space-y-2 mt-3 pl-2">
                          <div className="flex items-center text-xs text-gray-500">
                              <Tag size={12} className="mr-2 text-slate-400" />
                              <span className="font-medium text-slate-700">{client.leadType || 'General Lead'}</span>
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Phone size={12} className="mr-2 text-slate-400" />
                              {client.phone ? client.phone : <span className="italic text-gray-400">No phone</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Cake size={12} className="mr-2 text-slate-400" />
                              {client.dateOfBirth ? client.dateOfBirth : <span className="italic text-gray-400">No DOB</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <MapPin size={12} className="mr-2 text-slate-400" />
                              {client.address ? <span className="truncate max-w-[180px]">{client.address}</span> : <span className="italic text-gray-400">No State/Address</span>}
                          </div>

                          {/* Last Contact Footer */}
                          <div className="flex items-center text-xs text-slate-400 pt-2 border-t border-gray-50 mt-2">
                              <CalendarIcon size={12} className="mr-2 opacity-70" />
                              Last Contact: {client.lastContactDate}
                          </div>
                      </div>

                      {/* Action Buttons Overlay */}
                      <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 rounded-lg border border-indigo-100 z-10 pointer-events-none">
                          <div className="flex items-center gap-2 pointer-events-auto">
                              <button 
                                onClick={() => moveStage(client.id, 'prev')}
                                disabled={stage === PipelineStage.NEW_LEAD}
                                className="p-2 rounded-full bg-gray-100 hover:bg-gray-200 disabled:opacity-30 text-gray-600 border border-gray-200"
                                title="Move Back"
                              >
                                 <ChevronLeft size={16} />
                              </button>

                              <button 
                                 onClick={() => openEditModal(client)}
                                 className="flex items-center gap-1 px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-lg shadow-md hover:bg-indigo-700 transition-colors"
                              >
                                 <Edit2 size={12} /> Edit Lead
                              </button>

                              <button 
                                 onClick={() => moveStage(client.id, 'next')}
                                 disabled={stage === PipelineStage.BAD_NUMBER}
                                 className="p-2 rounded-full bg-indigo-50 hover:bg-indigo-100 disabled:opacity-30 text-indigo-600 border border-indigo-100"
                                 title="Move Next"
                              >
                                 <ChevronRight size={16} />
                              </button>
                          </div>
                      </div>
                    </div>
                  ))}
                  <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="w-full py-2 border border-dashed border-gray-300 text-gray-400 rounded-lg text-sm hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
                  >
                      <Plus size={14} /> Add Card
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Appointment Scheduling Modal */}
      {isApptModalOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-sm ring-1 ring-black/5 animate-fade-in flex flex-col">
                  <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl shrink-0">
                      <h3 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                          <CalendarIcon size={18} className="text-indigo-600" /> Schedule Appointment
                      </h3>
                      <button onClick={() => { setIsApptModalOpen(false); setPendingMove(null); }} className="text-gray-400 hover:text-gray-600 transition-colors">
                          <X size={20} />
                      </button>
                  </div>

                  <div className="p-6 space-y-4">
                      <p className="text-sm text-slate-500 mb-2">
                          Confirm the date and time for this appointment. It will be automatically added to your calendar.
                      </p>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
                          <div className="relative">
                              <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                              <input 
                                  type="date"
                                  className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={apptDetails.date}
                                  onChange={(e) => setApptDetails(prev => ({...prev, date: e.target.value}))}
                              />
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Time</label>
                          <div className="relative">
                              <Clock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                              <input 
                                  type="time"
                                  className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={apptDetails.time}
                                  onChange={(e) => setApptDetails(prev => ({...prev, time: e.target.value}))}
                              />
                          </div>
                      </div>

                      <div className="pt-2 flex gap-3">
                          <button 
                              onClick={() => { setIsApptModalOpen(false); setPendingMove(null); }}
                              className="flex-1 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors text-sm"
                          >
                              Cancel
                          </button>
                          <button 
                              onClick={handleConfirmAppointment}
                              className="flex-1 py-2 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors shadow-md"
                          >
                              Set Appointment
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Policy Details Modal (Application/Underwriting) */}
      {isPolicyModalOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-lg ring-1 ring-black/5 animate-fade-in flex flex-col max-h-[90vh]">
                  <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl shrink-0">
                      <h3 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                          <ShieldCheck size={18} className="text-indigo-600" /> New Policy Details
                      </h3>
                      <button onClick={() => { setIsPolicyModalOpen(false); setPendingPolicyMove(null); }} className="text-gray-400 hover:text-gray-600 transition-colors">
                          <X size={20} />
                      </button>
                  </div>

                  <div className="p-6 space-y-4 overflow-y-auto">
                      <p className="text-sm text-slate-500 mb-4 bg-blue-50 border border-blue-100 p-3 rounded-lg">
                          Enter the application details to move this lead to <b>{pendingPolicyMove?.stage}</b>. This will automatically add them to your Book of Business and Applications list.
                      </p>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Carrier</label>
                              {carrierOptions.length > 0 ? (
                                  <select 
                                      className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      value={policyForm.carrier}
                                      onChange={(e) => setPolicyForm({...policyForm, carrier: e.target.value})}
                                  >
                                      <option value="">Select Carrier...</option>
                                      {carrierOptions.map(c => <option key={c} value={c}>{c}</option>)}
                                  </select>
                              ) : (
                                  <input 
                                      type="text" 
                                      className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      placeholder="e.g. Mutual of Omaha"
                                      value={policyForm.carrier}
                                      onChange={(e) => setPolicyForm({...policyForm, carrier: e.target.value})}
                                  />
                              )}
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Policy Type</label>
                              <select 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.policyType}
                                  onChange={(e) => setPolicyForm({...policyForm, policyType: e.target.value as PolicyType})}
                              >
                                  {Object.values(PolicyType).map(t => <option key={t} value={t}>{t}</option>)}
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Product Name</label>
                          {productOptions.length > 0 ? (
                              <select 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.productName}
                                  onChange={(e) => setPolicyForm({...policyForm, productName: e.target.value})}
                              >
                                  <option value="">Select Product...</option>
                                  {productOptions.map(p => <option key={p} value={p}>{p}</option>)}
                              </select>
                          ) : (
                              <input 
                                  type="text" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  placeholder="e.g. Living Promise Graded"
                                  value={policyForm.productName}
                                  onChange={(e) => setPolicyForm({...policyForm, productName: e.target.value})}
                              />
                          )}
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Annual Premium</label>
                              <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                                  <input 
                                      type="number" 
                                      className="w-full pl-7 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      placeholder="0.00"
                                      value={policyForm.premium}
                                      onChange={(e) => setPolicyForm({...policyForm, premium: e.target.value})}
                                  />
                              </div>
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Coverage Amount</label>
                              <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                                  <input 
                                      type="number" 
                                      className="w-full pl-7 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      placeholder="0"
                                      value={policyForm.coverageAmount}
                                      onChange={(e) => setPolicyForm({...policyForm, coverageAmount: e.target.value})}
                                  />
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Policy Number</label>
                              <input 
                                  type="text" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  placeholder="Or 'Pending'"
                                  value={policyForm.policyNumber}
                                  onChange={(e) => setPolicyForm({...policyForm, policyNumber: e.target.value})}
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Start Date</label>
                              <input 
                                  type="date" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.startDate}
                                  onChange={(e) => setPolicyForm({...policyForm, startDate: e.target.value})}
                              />
                          </div>
                      </div>

                      <div className="pt-2 flex gap-3">
                          <button 
                              onClick={() => { setIsPolicyModalOpen(false); setPendingPolicyMove(null); }}
                              className="flex-1 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors text-sm"
                          >
                              Cancel
                          </button>
                          <button 
                              onClick={handleSavePolicyMove}
                              disabled={!policyForm.carrier || !policyForm.premium}
                              className="flex-1 py-2 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                          >
                              <Save size={16} /> Save & Move Lead
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Quick Scripts Modal */}
      {isScriptsOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl h-[85vh] flex flex-col animate-fade-in relative overflow-hidden">
                  <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                      <h3 className="font-bold text-slate-800 flex items-center gap-2">
                          <BookOpen size={20} className="text-indigo-600" /> Quick Script Access
                      </h3>
                      <button onClick={() => setIsScriptsOpen(false)} className="text-gray-400 hover:text-gray-600">
                          <X size={24} />
                      </button>
                  </div>
                  <div className="flex-1 overflow-hidden">
                      <ScriptLibrary />
                  </div>
              </div>
          </div>
      )}

      {/* Import Modal */}
      {isImportModalOpen && (
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-2xl ring-1 ring-black/5 flex flex-col max-h-[80vh]">
                  <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                      <h3 className="font-bold text-xl text-slate-800 flex items-center gap-2">
                          <Upload size={20} className="text-indigo-600" /> Import Leads
                      </h3>
                      <button onClick={() => { setIsImportModalOpen(false); setImportStep('UPLOAD'); }} className="text-gray-400 hover:text-gray-600">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 flex-1 overflow-y-auto">
                      {importStep === 'UPLOAD' ? (
                          <div className="flex flex-col items-center justify-center h-full space-y-6">
                              <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center">
                                  <FileSpreadsheet size={40} className="text-indigo-600" />
                              </div>
                              <div className="text-center">
                                  <h4 className="text-lg font-bold text-slate-800">Upload CSV File</h4>
                                  <p className="text-slate-500 text-sm mt-1">Select a CSV file containing your lead data.</p>
                              </div>
                              <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 text-slate-700 font-medium py-2 px-6 rounded-lg shadow-sm transition-colors">
                                  <span className="flex items-center gap-2"><Upload size={16} /> Choose File</span>
                                  <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
                              </label>
                              <div className="bg-slate-50 p-4 rounded-lg text-xs text-slate-500 max-w-md text-center border border-slate-200">
                                  Tip: Ensure your file has a header row. We'll help you map the columns in the next step.
                              </div>
                          </div>
                      ) : (
                          <div className="space-y-6">
                              <div className="bg-green-50 border border-green-200 p-4 rounded-lg flex items-start gap-3">
                                  <CheckCircle2 size={20} className="text-green-600 shrink-0 mt-0.5" />
                                  <div>
                                      <h4 className="font-bold text-green-900 text-sm">File Loaded Successfully</h4>
                                      <p className="text-green-700 text-xs mt-1">Found {csvData.length} rows and {csvHeaders.length} columns. Please map the fields below.</p>
                                  </div>
                              </div>

                              <div className="space-y-4">
                                  {Object.keys(fieldMapping).map((systemField) => (
                                      <div key={systemField} className="grid grid-cols-2 gap-4 items-center">
                                          <label className="text-sm font-bold text-slate-600 uppercase flex justify-end">
                                              {systemField.replace(/([A-Z])/g, ' $1').trim()}
                                          </label>
                                          <div className="flex items-center gap-2">
                                              <ArrowRight size={14} className="text-gray-300" />
                                              <select 
                                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
                                                  value={fieldMapping[systemField]}
                                                  onChange={(e) => setFieldMapping({...fieldMapping, [systemField]: e.target.value})}
                                              >
                                                  <option value="">-- Select Column --</option>
                                                  {csvHeaders.map(header => (
                                                      <option key={header} value={header}>{header}</option>
                                                  ))}
                                              </select>
                                          </div>
                                      </div>
                                  ))}
                              </div>
                          </div>
                      )}
                  </div>

                  <div className="p-5 border-t border-gray-100 bg-gray-50 rounded-b-xl flex justify-end">
                      {importStep === 'MAP' && (
                          <button 
                              onClick={executeImport}
                              disabled={!fieldMapping.firstName || !fieldMapping.lastName}
                              className="px-6 py-2.5 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 shadow-md"
                          >
                              Complete Import <ArrowRight size={16} />
                          </button>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Add Lead Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-white/90 backdrop-blur-md">
            <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-md ring-1 ring-black/5 flex flex-col max-h-[90vh]">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-white rounded-t-xl shrink-0">
                    <h3 className="font-bold text-slate-800">Add New Lead</h3>
                    <button onClick={() => setIsAddModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-6 space-y-4 bg-white overflow-y-auto">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">First Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newLead.firstName}
                                onChange={(e) => setNewLead({...newLead, firstName: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Last Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newLead.lastName}
                                onChange={(e) => setNewLead({...newLead, lastName: e.target.value})}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                        <input 
                            type="email" 
                            className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={newLead.email}
                            onChange={(e) => setNewLead({...newLead, email: e.target.value})}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
