import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Users, FileText, Settings, Shield, Menu, Sparkles, 
  BarChart3, CheckSquare, Calendar as CalendarIcon, DollarSign, GraduationCap, 
