                         {client.leadType && (
                             <span className={`text-[10px] uppercase tracking-wider font-bold px-1.5 py-0.5 rounded border 
                                ${client.leadType === 'FEX' ? 'bg-rose-50 text-rose-600 border-rose-100' : 
                                  client.leadType === 'MP' ? 'bg-blue-50 text-blue-600 border-blue-100' : 
                                  client.leadType === 'IUL' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                  'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>
                                 {client.leadType}
                             </span>
                         )}
                      </div>

                      {/* Contact Details */}
                      <div className="space-y-2 mt-3 pl-2">
                          <div className="flex items-center text-xs text-gray-500">
                              <Tag size={12} className="mr-2 text-slate-400" />
                              <span className="font-medium text-slate-700">{client.leadType || 'General Lead'}</span>
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Phone size={12} className="mr-2 text-slate-400" />
                              {client.phone ? client.phone : <span className="italic text-gray-400">No phone</span>}
                          </div>
                          <div className="flex items-center text-xs text-gray-500">
                              <Cake size={12} className="mr-2 text-slate-400" />
