                          <button 
                              onClick={handleConfirmAppointment}
                              className="flex-1 py-2 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors shadow-md"
                          >
                              Set Appointment
