      const annualPremium = Number(editingPolicy.premium) || 0;
      // Auto-calc commission if not provided (approx 90% default)
      const commission = Number(editingPolicy.commission) || (annualPremium * 0.9);

      let endDate = editingPolicy.endDate;
      const startDate = editingPolicy.startDate || new Date().toISOString().split('T')[0];

      if (editingPolicy.type === PolicyType.TERM) {
          const start = new Date(startDate);
          start.setFullYear(start.getFullYear() + termLength);
          endDate = start.toISOString().split('T')[0];
      } else {
          // Default for perm products (Age 100+)
          const start = new Date(startDate);
          start.setFullYear(start.getFullYear() + 100); 
          endDate = start.toISOString().split('T')[0];
      }

      // Auto-Activate Status if Start Date is reached
      const todayStr = new Date().toISOString().split('T')[0];
      const isEffective = startDate <= todayStr;

      const finalStatus = isEffective ? PolicyStatus.ACTIVE : editingPolicy.status || PolicyStatus.PENDING;

      const policyData: Policy = {
          id: editingPolicy.id || `pol-${Date.now()}`,
          type: editingPolicy.type || PolicyType.TERM,
          policyNumber: editingPolicy.policyNumber,
          carrier: editingPolicy.carrier,
          premium: annualPremium,
          coverageAmount: Number(editingPolicy.coverageAmount) || 0,
          commission: commission,
          startDate: startDate,
          endDate: endDate,
          status: finalStatus,
          productName: editingPolicy.productName || 'Manual Policy',
          isPaidOut: finalStatus === PolicyStatus.ACTIVE // Assume active policies added manually are paid/in-force
      };

      let updatedPolicies;
      if (editingPolicy.id) {
          // Edit existing
          updatedPolicies = selectedClient.policies.map(p => p.id === editingPolicy.id ? policyData : p);
      } else {
