                                        className="w-full pl-6 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                                        value={editingPolicy.commission || ''}
                                        onChange={(e) => setEditingPolicy({...editingPolicy, commission: parseFloat(e.target.value)})}
                                        placeholder="Auto"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="p-5 border-t border-gray-100 bg-gray-50 rounded-b-xl flex gap-3 shrink-0">
                        <button 
                            onClick={() => setIsPolicyModalOpen(false)}
                            className="flex-1 py-2.5 bg-white border border-gray-200 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button 
                            onClick={handleSavePolicy}
                            disabled={!editingPolicy.carrier || !editingPolicy.policyNumber}
                            className="flex-1 py-2.5 bg-indigo-600 text-white rounded-lg font-medium hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <Save size={16} /> Save Policy
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    );
  }

  // --- List View (Default) ---
  return (
    <div className="animate-fade-in space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">My Contacts</h2>
        <div className="flex gap-2">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                <input 
                    type="text" 
                    placeholder="Search name, email, phone..." 
                    className="pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900 w-64"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="relative">
                <select 
                    className="appearance-none pl-4 pr-8 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-700 cursor-pointer"
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                >
                    <option value="ALL">All Statuses</option>
                    {Object.values(PipelineStage).map(s => (
                        <option key={s} value={s}>{s}</option>
                    ))}
                </select>
                <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={14} />
            </div>

            <div className="relative">
                <select 
                    className="appearance-none pl-4 pr-8 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-700 cursor-pointer"
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                >
                    <option value="NAME">Sort by Name</option>
                    <option value="RECENT">Sort by Recent</option>
                    <option value="PREMIUM">Sort by Premium</option>
                </select>
                <ArrowUpDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={14} />
            </div>

            <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
            >
                <Plus size={16} /> Add Contact
            </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
                <thead>
                    <tr className="bg-gray-50 border-b border-gray-100 text-xs font-bold text-slate-500 uppercase tracking-wider">
                        <th className="px-6 py-4">Client</th>
                        <th className="px-6 py-4">Contact Info</th>
                        <th className="px-6 py-4">Stage</th>
                        <th className="px-6 py-4">Policies</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                    {processedClients.length === 0 ? (
                        <tr>
                            <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                                No clients found matching your search.
                            </td>
                        </tr>
                    ) : processedClients.map((client) => (
                        <tr 
                            key={client.id} 
                            onClick={() => onSelectClient(client)}
                            className="hover:bg-slate-50 transition-colors cursor-pointer group"
                        >
                            <td className="px-6 py-4">
                                <div className="flex items-center gap-3">
                                    <img 
                                        src={client.avatarUrl || `https://ui-avatars.com/api/?name=${client.firstName}+${client.lastName}`} 
                                        alt="" 
                                        className="w-10 h-10 rounded-full object-cover bg-gray-200"
                                    />
                                    <div>
                                        <div className="font-bold text-slate-800 text-sm">{client.firstName} {client.lastName}</div>
                                        <div className="text-xs text-gray-500">Added: {client.lastContactDate}</div>
                                    </div>
                                </div>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex flex-col gap-1 text-sm text-slate-600">
                                    <div className="flex items-center gap-2">
                                        <Mail size={14} className="text-gray-400" />
                                        {client.email}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Phone size={14} className="text-gray-400" />
                                        {client.phone}
                                    </div>
                                </div>
                            </td>
                            <td className="px-6 py-4">
                                <span className={`px-2.5 py-1 rounded-full text-xs font-bold ${
                                    client.pipelineStage === PipelineStage.ISSUED ? 'bg-green-100 text-green-700' :
                                    client.pipelineStage === PipelineStage.NEW_LEAD ? 'bg-blue-100 text-blue-700' :
                                    'bg-yellow-100 text-yellow-700'
                                }`}>
                                    {client.pipelineStage}
                                </span>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                    <FileText size={16} className="text-gray-400" />
                                    <span className="text-sm font-medium text-slate-700">{client.policies.length} Policies</span>
                                </div>
                            </td>
                            <td className="px-6 py-4 text-right">
                                <ChevronRight className="inline-block text-gray-300 group-hover:text-indigo-500 transition-colors" size={20} />
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
      </div>

      {/* Add Client Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center z-50 p-4 bg-slate-900/60 backdrop-blur-md">
            <div className="bg-white rounded-xl shadow-2xl border border-gray-100 w-full max-w-md ring-1 ring-black/5 flex flex-col">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <h3 className="font-bold text-xl text-slate-800">Add New Contact</h3>
                    <button onClick={() => setIsAddModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                        <X size={24} />
                    </button>
                </div>
                <div className="p-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">First Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newClient.firstName}
                                onChange={(e) => setNewClient({...newClient, firstName: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Last Name</label>
                            <input 
                                type="text" 
                                className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                value={newClient.lastName}
                                onChange={(e) => setNewClient({...newClient, lastName: e.target.value})}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                        <input 
                            type="email" 
                            className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={newClient.email}
                            onChange={(e) => setNewClient({...newClient, email: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                        <input 
                            type="tel" 
                            className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                            value={newClient.phone}
                            onChange={(e) => setNewClient({...newClient, phone: e.target.value})}
                        />
                    </div>

                    <button 
                        onClick={handleAddClient}
                        disabled={!newClient.firstName || !newClient.lastName}
                        className="w-full py-2.5 bg-indigo-600 text-white rounded-lg font-bold text-sm hover:bg-indigo-700 transition-colors shadow-sm disabled:opacity-50 mt-2"
                    >
                        Create Contact
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';

export type Role = 'ADMIN' | 'AGENCY_OWNER' | 'MANAGER' | 'AGENT' | 'RECRUIT';

export type SubscriptionStatus = 'active' | 'past_due' | 'cancelled' | 'trial';
export type SubscriptionPlan = 'starter' | 'professional' | 'enterprise';

export enum PolicyType {
  TERM = 'Term Life',
  WHOLE = 'Whole Life',
  IUL = 'IUL',
  ANNUITY = 'Annuity',
  FINAL_EXPENSE = 'Final Expense',
  HEALTH = 'Health'
}

export enum PolicyStatus {
  ACTIVE = 'Active',
  PENDING = 'Pending',
  EXPIRED = 'Expired',
  CANCELLED = 'Cancelled',
  LAPSED = 'Lapsed'
}

export enum PipelineStage {
  NEW_LEAD = 'New Lead',
  CONTACTED = 'Contacted',
  APPOINTMENT_SET = 'Appointment Set',
  APPLICATION_TAKEN = 'Application Approved',
  UNDERWRITING = 'Underwriting',
  ISSUED = 'Issued',
  NOT_INTERESTED = 'Not Interested',
  BAD_NUMBER = 'Bad Number'
}

export interface Policy {
  id: string;
  applicationId?: string; // ID of the application that generated this policy
  type: PolicyType;
  productName?: string; // Specific product name
  policyNumber: string;
  carrier: string;
  premium: number; // Annual Premium
  coverageAmount: number; // Face Amount
  commission: number;
  startDate: string;
  endDate: string;
  status: PolicyStatus;
  isPaidOut?: boolean;
  documentUrl?: string; // URL/Base64 of the original application document
}

export interface Client {
  id: string;
  agentId: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  dateOfBirth?: string;
  address: string;
  policies: Policy[];
  notes: string;
  avatarUrl?: string;
  pipelineStage: PipelineStage;
  leadSource: string;
  leadType?: 'FEX' | 'MP' | 'IUL' | 'VET'; // Added specific lead type
  lastContactDate: string;
}

export interface Application {
  id: string;
  clientId: string;
  clientName: string;
  carrier: string;
  product: string;
  policyNumber?: string; // Added field
  submittedDate: string;
  policyStartDate?: string; // Effective Date requested/issued
  premium: number;
  coverageAmount?: number;
  status: 'Submitted' | 'Underwriting' | 'Approved' | 'Issued' | 'Declined';
  notes: string;
  documentUrl?: string; // URL/Base64 of the uploaded application document
}

export interface TeamMember {
  id: string;
  name: string;
  email: string;
  role: Role;
  production: number;
  activePolicies: number;
  avatarUrl: string;
  defaultCompLevel: number; // e.g. 100
  carrierCompLevels?: Record<string, number>; // { 'Aetna': 110 }
}

export interface User {
  id: string;
  email: string;
  name: string;
  role: Role;
  avatarUrl: string;
  phone?: string;
  npn?: string;
}

// Extended interface for Super Admin view
export interface SaaSUser extends User {
  status: SubscriptionStatus;
  plan: SubscriptionPlan;
  joinDate: string;
  lastLogin: string;
  monthlyFee: number;
  agencyName?: string;
}

export interface ActivityItem {
  id: string;
  user: string;
  action: string;
  target: string;
  timestamp: string;
  type: 'POLICY' | 'CLIENT' | 'SYSTEM' | 'LEAD';
}

export interface Referral {
  id: string;
  referrerName: string;
  referredProspect: string;
  date: string;
  status: 'New' | 'Contacted' | 'Closed - Won' | 'Closed - Lost';
  rewardStatus: 'Pending' | 'Paid' | 'Ineligible';
}

export interface StatCardProps {
  title: string;
  value: string;
  trend?: string;
  trendUp?: boolean;
  icon: React.ReactNode;
  subtitle?: string;
}

export type ViewState = 
  | 'DASHBOARD' 
  | 'MANAGER_DASHBOARD'
  | 'PLATFORM_ADMIN' 
  | 'QUOTER' 
  | 'LEAD_STORE'
  | 'THE_DOJO'
  | 'CARRIERS' // New View
  | 'CLIENTS' 
