                                  value={apptDetails.date}
                                  onChange={(e) => setApptDetails(prev => ({...prev, date: e.target.value}))}
                              />
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Time</label>
