                                  onChange={(e) => setApptDetails(prev => ({...prev, time: e.target.value}))}
                              />
                          </div>
                      </div>

                      <div className="pt-2 flex gap-3">
                          <button 
                              onClick={() => { setIsApptModalOpen(false); setPendingMove(null); }}
                              className="flex-1 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors text-sm"
