                      {policyForm.policyType === PolicyType.TERM && (
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Term Length (Years)</label>
                              <select 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.termLength}
                                  onChange={(e) => setPolicyForm({...policyForm, termLength: parseInt(e.target.value)})}
                              >
                                  <option value={10}>10 Years</option>
                                  <option value={15}>15 Years</option>
                                  <option value={20}>20 Years</option>
                                  <option value={25}>25 Years</option>
                                  <option value={30}>30 Years</option>
                                  <option value={35}>35 Years</option>
                              </select>
                          </div>
                      )}

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Product Name</label>
                          {productOptions.length > 0 ? (
                              <select 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.productName}
                                  onChange={(e) => setPolicyForm({...policyForm, productName: e.target.value})}
                              >
                                  <option value="">Select Product...</option>
                                  {productOptions.map(p => <option key={p} value={p}>{p}</option>)}
                              </select>
                          ) : (
                              <input 
                                  type="text" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  placeholder="e.g. Living Promise Graded"
                                  value={policyForm.productName}
                                  onChange={(e) => setPolicyForm({...policyForm, productName: e.target.value})}
                              />
                          )}
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Annual Premium</label>
                              <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                                  <input 
                                      type="number" 
                                      className="w-full pl-7 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      placeholder="0.00"
                                      value={policyForm.premium}
                                      onChange={(e) => setPolicyForm({...policyForm, premium: e.target.value})}
                                  />
                              </div>
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Coverage Amount</label>
                              <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                                  <input 
                                      type="number" 
                                      className="w-full pl-7 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                      placeholder="0"
                                      value={policyForm.coverageAmount}
                                      onChange={(e) => setPolicyForm({...policyForm, coverageAmount: e.target.value})}
                                  />
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Policy Number</label>
                              <input 
                                  type="text" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  placeholder="Or 'Pending'"
                                  value={policyForm.policyNumber}
                                  onChange={(e) => setPolicyForm({...policyForm, policyNumber: e.target.value})}
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Start Date</label>
                              <input 
                                  type="date" 
                                  className="w-full border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                                  value={policyForm.startDate}
                                  onChange={(e) => setPolicyForm({...policyForm, startDate: e.target.value})}
                              />
