                              value={policyForm.status}
                              onChange={(e) => setPolicyForm({...policyForm, status: e.target.value as PolicyStatus})}
                          >
                              {Object.values(PolicyStatus).map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                      </div>

                      <div className="pt-2 flex gap-3">
