                      </h3>
                      <button onClick={() => setIsScriptsOpen(false)} className="text-gray-400 hover:text-gray-600">
                          <X size={24} />
                      </button>
                  </div>
                  <div className="flex-1 overflow-hidden">
                      <ScriptLibrary />
                  </div>
              </div>
          </div>
