                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Coverage</label>
                                <div className="relative">
                                    <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                                    <input 
                                        type="number"
                                        className="w-full pl-6 border border-gray-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                                        value={editingPolicy.coverageAmount || ''}
                                        onChange={(e) => setEditingPolicy({...editingPolicy, coverageAmount: parseFloat(e.target.value)})}
                                        placeholder="0"
