        alert(`Password reset email sent to ${editingUser?.email}.`);
    };

    const applyQuickFilter = (status: string) => {
        setStatusFilter(status);
        setCurrentPage(1); 
    };

    // --- Commission CSV Parsers ---

    const parsePercentage = (val: string): number => {
        if (!val) return 0;
        const clean = val.replace(/[%]/g, '').trim();
        const num = parseFloat(clean);
        return isNaN(num) ? 0 : num / 100;
    };

    const parseCSVLine = (line: string): string[] => {
        const result = [];
        let start = 0;
        let inQuotes = false;

        for (let i = 0; i < line.length; i++) {
            if (line[i] === '"') {
                inQuotes = !inQuotes;
            } else if (line[i] === ',' && !inQuotes) {
                let cell = line.substring(start, i);
                cell = cell.trim();
                if (cell.startsWith('"') && cell.endsWith('"')) {
                    cell = cell.substring(1, cell.length - 1).replace(/""/g, '"');
                }
                result.push(cell);
                start = i + 1;
            }
        }
        let lastCell = line.substring(start);
        lastCell = lastCell.trim();
        if (lastCell.startsWith('"') && lastCell.endsWith('"')) {
            lastCell = lastCell.substring(1, lastCell.length - 1).replace(/""/g, '"');
        }
        result.push(lastCell);

        return result;
    };

    const handleGridUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploadStatus('Parsing Matrix CSV...');

        const reader = new FileReader();
        reader.onload = (evt) => {
            try {
                const text = evt.target?.result as string;
                const rows = text.split(/\r\n|\n/);

                // 1. Identify Header Row
                let headerRowIndex = -1;
                let headerCols: string[] = [];

                for (let i = 0; i < Math.min(rows.length, 30); i++) {
                    const cols = parseCSVLine(rows[i]);
                    if (cols.includes('Company') && cols.includes('Product')) {
                        headerRowIndex = i;
                        headerCols = cols;
                        break;
                    }
                }

                if (headerRowIndex === -1) {
                    setUploadStatus('Error: Could not find standard headers (Company, Product). Please check file format.');
                    return;
                }

                // 2. Map Column Indices
                const carrierIdx = headerCols.findIndex(h => h.trim() === 'Company');
                const productIdx = headerCols.findIndex(h => h.trim() === 'Product');
                const compYearIdx = headerCols.findIndex(h => h.trim() === 'Comp Year' || h.trim() === 'Comp_Year');

                if (carrierIdx === -1 || productIdx === -1) {
                    setUploadStatus('Error: "Company" or "Product" columns are missing in the identified header row.');
                    return;
                }

                // 3. Map Level Columns
                const colIndices: Record<string, number> = {};

                headerCols.forEach((h, i) => {
                    const cleanH = h.trim();
                    if (cleanH === 'FA') colIndices['70'] = i;
                    else if (cleanH === 'SFA') colIndices['85'] = i;
                    else if (cleanH === 'SM') colIndices['100'] = i;
                    else if (cleanH === 'SM II') colIndices['107.5'] = i;
                    else if (cleanH === 'ED/SM III') colIndices['115'] = i;
                    else if (cleanH.includes('ED (B1)') || cleanH.includes('SED+')) colIndices['120'] = i;
                    else if (cleanH.includes('ED+ (B2)')) colIndices['125'] = i;
                    else if (cleanH.includes('ED+ (B3)')) colIndices['130'] = i;
                    else if (cleanH.includes('RANDY SPECIAL')) colIndices['138'] = i;
                });

                // Deep copy to ensure state update triggers properly
                const newRegistry: CommissionRegistry = JSON.parse(JSON.stringify(commissionRegistry));
                let processedCount = 0;

                // 4. Iterate Data Rows
                for (let i = headerRowIndex + 1; i < rows.length; i++) {
                    if (!rows[i].trim()) continue; 

                    const cols = parseCSVLine(rows[i]);
                    if (cols.length <= Math.max(carrierIdx, productIdx)) continue;

                    const carrier = cols[carrierIdx]?.trim();
                    const product = cols[productIdx]?.trim();
                    const compYearRaw = compYearIdx !== -1 ? cols[compYearIdx] : '';
                    const compYear = compYearRaw ? compYearRaw.trim() : '';

                    if (!carrier || !product || carrier === 'Company') continue;

                    if (!newRegistry[carrier]) newRegistry[carrier] = {};
                    if (!newRegistry[carrier][product]) newRegistry[carrier][product] = {};

                    const compYearLower = compYear.toLowerCase();
                    const isRenewal = compYearLower.includes('renewal') || compYearLower.includes('year 2') || compYearLower.includes('years 2');
                    const isExcess = compYearLower.includes('excess');

                    Object.entries(colIndices).forEach(([level, colIdx]) => {
                        if (cols.length <= colIdx) return;

                        const rateStr = cols[colIdx];
                        if (!rateStr) return;

                        const rate = parsePercentage(rateStr);

                        if (!newRegistry[carrier][product][level]) {
                            newRegistry[carrier][product][level] = { fyc: 0, renewals: 0 };
                        }

                        // Always populate FYC for visibility in grid, even if technically renewal row in CSV
                        newRegistry[carrier][product][level].fyc = rate;

                        if (isRenewal) {
                            if (rate > 0) newRegistry[carrier][product][level].renewals = rate;
                        } else if (isExcess) {
                            newRegistry[carrier][product][level].excess = rate;
                        }
                    });
                    processedCount++;
                }

                setCommissionRegistry(newRegistry);
                // Try saving immediately to catch errors early
                try {
                    localStorage.setItem('arise_commission_registry', JSON.stringify(newRegistry));
                    setUploadStatus(`Success! Processed ${processedCount} rows. Registry Saved.`);
                } catch (storageError) {
                    console.error("Storage error:", storageError);
                    setUploadStatus(`Processed ${processedCount} rows, but failed to save to storage (Quota Exceeded). Try reducing file size.`);
                }

            } catch (err) {
                console.error("Parsing error:", err);
                setUploadStatus('Error parsing CSV file. Please check format.');
            }
        };
        reader.readAsText(file);
    };

    const handleAdvanceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
