            case 'STAFF': return 'bg-teal-100 text-teal-700 border-teal-200';
            case 'RECRUIT': return 'bg-gray-100 text-gray-700 border-gray-200';
            default: return 'bg-gray-100 text-gray-600 border-gray-200';
