import React, { useState, useEffect, useRef } from 'react';
import { generateSaaSUsers } from '../services/mockData';
import { SaaSUser, Role, SubscriptionStatus, SubscriptionPlan, CommissionRegistry } from '../types';
import { 
    Search, Shield, Edit2, Trash2, X, Save, Upload, Database, CreditCard, Activity, Lock
} from 'lucide-react';

const PlatformAdmin: React.FC = () => {
    // --- User Management State ---
    const [users, setUsers] = useState<SaaSUser[]>(() => {
        // Try to persist for demo feel
        try {
            const saved = localStorage.getItem('arise_saas_users');
            return saved ? JSON.parse(saved) : generateSaaSUsers(50);
        } catch {
            return generateSaaSUsers(50);
        }
    });
    const [searchTerm, setSearchTerm] = useState('');
    const [editingUser, setEditingUser] = useState<SaaSUser | null>(null);
    const [editForm, setEditForm] = useState<Partial<SaaSUser>>({});
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);

    // --- Commission Registry State ---
    const [registryStats, setRegistryStats] = useState({ carriers: 0, products: 0 });
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [uploadStatus, setUploadStatus] = useState<'IDLE' | 'PARSING' | 'SUCCESS' | 'ERROR'>('IDLE');

    useEffect(() => {
        localStorage.setItem('arise_saas_users', JSON.stringify(users));
    }, [users]);

    useEffect(() => {
        // Load stats
        try {
            const reg: CommissionRegistry = JSON.parse(localStorage.getItem('arise_commission_registry') || '{}');
            const carriers = Object.keys(reg).length;
            const products = Object.values(reg).reduce((acc, curr) => acc + Object.keys(curr).length, 0);
            setRegistryStats({ carriers, products });
        } catch (e) { console.error(e); }
    }, [uploadStatus]);

    // --- User Actions ---
    const handleEditUser = (user: SaaSUser) => {
        setEditingUser(user);
        setEditForm({ ...user });
        setIsEditModalOpen(true);
    };

    const handleSaveUser = () => {
        if (!editingUser) return;
        setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...editForm } as SaaSUser : u));
        setIsEditModalOpen(false);
        setEditingUser(null);
    };

    const handleDeleteUser = (id: string) => {
        if (window.confirm('Are you sure you want to delete this user?')) {
            setUsers(prev => prev.filter(u => u.id !== id));
        }
    };

    // --- Commission Upload ---
    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploadStatus('PARSING');
        const reader = new FileReader();
        reader.onload = (evt) => {
            try {
                const text = evt.target?.result as string;
                const lines = text.split(/\r\n|\n/);
                const registry: CommissionRegistry = {};

                // Expected CSV: Carrier, Product, Level, FYC, Renewals
                // Skip header
                for (let i = 1; i < lines.length; i++) {
                    const line = lines[i].trim();
                    if (!line) continue;
                    const [carrier, product, levelStr, fycStr, renStr] = line.split(',').map(s => s.trim());

                    if (!carrier || !product || !levelStr) continue;

                    if (!registry[carrier]) registry[carrier] = {};
                    if (!registry[carrier][product]) registry[carrier][product] = {};

                    const level = levelStr.replace('%', ''); // Allow "100%" or "100"
                    const fyc = parseFloat(fycStr); // Expect decimal e.g. 1.15 or 0.90
                    const renewals = parseFloat(renStr) || 0;

                    registry[carrier][product][level] = { fyc, renewals };
                }

                localStorage.setItem('arise_commission_registry', JSON.stringify(registry));
                setUploadStatus('SUCCESS');
                setTimeout(() => setUploadStatus('IDLE'), 3000);
            } catch (err) {
                console.error(err);
                setUploadStatus('ERROR');
            }
        };
        reader.readAsText(file);
    };

    // ... Rendering logic
    const filteredUsers = users.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="animate-fade-in space-y-8 pb-10">
            {/* Header */}
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <Shield className="text-purple-600" /> Platform Administration
                    </h2>
                    <p className="text-sm text-slate-500">Manage SaaS users, subscriptions, and global configurations.</p>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
                    <p className="text-sm text-gray-500 font-medium">Total Users</p>
                    <h3 className="text-3xl font-bold text-slate-800 mt-2">{users.length}</h3>
                </div>
                <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
                    <p className="text-sm text-gray-500 font-medium">Monthly Recurring Revenue</p>
                    <h3 className="text-3xl font-bold text-green-600 mt-2">
                        ${users.reduce((acc, u) => acc + (u.status === 'active' ? u.monthlyFee : 0), 0).toLocaleString()}
                    </h3>
                </div>
                <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
                    <p className="text-sm text-gray-500 font-medium">Commission Products</p>
                    <h3 className="text-3xl font-bold text-indigo-600 mt-2">{registryStats.products}</h3>
                    <p className="text-xs text-slate-400">across {registryStats.carriers} carriers</p>
                </div>
            </div>

            {/* Commission Management */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                    <div>
                        <h3 className="font-bold text-slate-800 flex items-center gap-2">
                            <Database size={18} className="text-indigo-600" /> Commission Registry
                        </h3>
                        <p className="text-sm text-gray-500">Upload global commission grids (CSV).</p>
                    </div>
                    <div>
                        <input 
                            type="file" 
                            accept=".csv"
                            ref={fileInputRef}
                            className="hidden"
                            onChange={handleFileUpload}
                        />
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            disabled={uploadStatus === 'PARSING'}
                            className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-700 font-bold rounded-lg hover:bg-indigo-100 transition-colors text-sm"
                        >
                            {uploadStatus === 'PARSING' ? 'Processing...' : (
                                <>
                                    <Upload size={16} /> Upload CSV
                                </>
                            )}
                        </button>
                    </div>
                </div>
                {uploadStatus === 'SUCCESS' && (
                    <div className="bg-green-50 p-3 text-center text-green-700 text-sm font-medium">
