                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <Shield className="text-indigo-600" /> Platform Administration
                    </h2>
                    <p className="text-sm text-slate-500">Super Admin Console • Managing {users.length.toLocaleString()} total users</p>
                </div>
                <div className="flex gap-3">
                    <span className="flex items-center gap-1 bg-green-50 text-green-700 px-3 py-1.5 rounded-full text-xs font-bold border border-green-100">
