           </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden w-full relative">
        <header className="bg-white border-b border-gray-100 p-4 flex items-center justify-between lg:hidden z-10 shrink-0">
