import React, { useState } from 'react';
import { ArrowRight, Lock, Mail, User as UserIcon, Loader2, Sparkles, PlayCircle } from 'lucide-react';
import { MOCK_USERS } from '../services/mockData';
import { User } from '../types';
import { AriseLogo } from './AriseLogo';

interface LoginProps {
    onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    const [activeTab, setActiveTab] = useState<'signin' | 'signup'>('signin');
    const [isLoading, setIsLoading] = useState(false);
    const [isDemoLoading, setIsDemoLoading] = useState(false);
    const [error, setError] = useState('');

    // Sign In State - Default to updated admin email
    const [email, setEmail] = useState('randy@arise.com');
    const [password, setPassword] = useState('password');

    // Sign Up State
    const [newName, setNewName] = useState('');
    const [newEmail, setNewEmail] = useState('');
    const [newPassword, setNewPassword] = useState('');

    const handleSignIn = (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        setTimeout(() => {
            const normalizedEmail = email.trim().toLowerCase();

            // 1. Check for persisted overrides (Saved in Settings)
            // This is critical for persisting user changes like avatars
            try {
                const savedUsersStr = localStorage.getItem('arise_users_overrides');
                if (savedUsersStr) {
                    const savedUsers = JSON.parse(savedUsersStr);
                    if (savedUsers[normalizedEmail]) {
                        onLogin(savedUsers[normalizedEmail]);
                        return;
                    }
                }
            } catch (e) {
                console.error("Error reading saved user data", e);
            }

            // 2. Fallback to Mock Data
            const user = MOCK_USERS.find(u => 
                u.email.toLowerCase() === normalizedEmail || 
                (normalizedEmail === 'alex@arise.com' && u.role === 'ADMIN')
            );

            if (user) {
                onLogin(user);
            } else {
                setError('Invalid email or password.');
                setIsLoading(false);
            }
        }, 800);
    };

    const handleSignUp = (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        if (!newName || !newEmail || !newPassword) {
            setError('Please fill in all fields');
            setIsLoading(false);
            return;
        }

        setTimeout(() => {
            // Simulate account creation for demo
            const newUser: User = {
                id: `u-${Date.now()}`,
                name: newName,
                email: newEmail,
                role: 'AGENT',
                avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newName)}&background=random`
            };
            onLogin(newUser);
        }, 800);
    };

    const handleDemoLogin = () => {
        setIsDemoLoading(true);
        setTimeout(() => {
            const demoUser: User = {
                id: 'demo-admin',
                name: 'Demo Admin',
                email: 'demo@arise.com',
                role: 'AGENCY_OWNER', // Give high privileges to show all features
                avatarUrl: 'https://ui-avatars.com/api/?name=Demo+Admin&background=0D9488&color=fff'
            };
            onLogin(demoUser);
        }, 1000);
    };

    return (
        <div className="min-h-screen bg-white flex flex-col items-center justify-center p-4">
            <div className="w-full max-w-md animate-fade-in">
                <div className="flex items-center justify-center gap-3 mb-8">
                    <div className="w-14 h-14 flex items-center justify-center">
                        <AriseLogo className="w-full h-full drop-shadow-md" />
                    </div>
                    <div className="text-center pt-1">
                        <h1 className="text-3xl font-bold text-slate-900 leading-none">
                            ARISE
                        </h1>
                        <p className="text-xs text-blue-600 font-bold tracking-widest mt-1 uppercase">
                            Agent Hub
                        </p>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow-xl border border-gray-100 overflow-hidden relative">
                    {/* Tabs */}
                    <div className="grid grid-cols-2 border-b border-gray-100">
                        <button 
                            onClick={() => { setActiveTab('signin'); setError(''); }}
                            className={`py-3 text-sm font-medium transition-colors ${activeTab === 'signin' ? 'border-b-2 border-blue-600 text-blue-600 bg-blue-50/30' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
                        >
                            Sign In
                        </button>
