                                            {notif.type === 'success' ? <CheckCircle2 size={16} /> : 
                                             notif.type === 'warning' ? <AlertCircle size={16} /> : <Info size={16} />}
                                        </div>
                                        <div>
                                            <p className="text-sm text-slate-700 font-medium leading-tight">{notif.text}</p>
                                            <p className="text-xs text-gray-400 mt-1">{notif.time}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="p-2 border-t border-gray-100 text-center">
                                <button className="text-xs font-bold text-slate-500 hover:text-slate-800">View Activity Log</button>
                            </div>
                        </div>
                    )}
                </div>

                <div className="h-6 w-px bg-gray-200 hidden sm:block"></div>

                {/* User Profile */}
                <div className="relative" ref={userMenuRef}>
                    <button 
                        onClick={() => setIsUserOpen(!isUserOpen)}
                        className="flex items-center gap-3 hover:bg-slate-50 p-1.5 rounded-lg transition-colors group"
                    >
                        <img 
                            src={user.avatarUrl} 
                            alt={user.name} 
                            className="w-8 h-8 rounded-full object-cover border border-gray-200 group-hover:border-indigo-200" 
                        />
                        <div className="hidden sm:block text-left">
                            <p className="text-sm font-bold text-slate-700 leading-none group-hover:text-indigo-700">{user.name}</p>
                            <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wide mt-0.5">
                                {user.role.replace('_', ' ')}
                            </p>
                        </div>
                        <ChevronDown size={14} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
                    </button>

                    {isUserOpen && (
                        <div className="absolute right-0 top-full mt-2 w-56 bg-white rounded-xl shadow-xl border border-gray-100 overflow-hidden animate-fade-in origin-top-right">
                            <div className="p-4 border-b border-gray-100 bg-slate-50/50">
                                <p className="text-sm font-bold text-slate-800">Signed in as</p>
                                <p className="text-xs text-slate-500 truncate">{user.email}</p>
                            </div>
                            <div className="p-1">
                                <button 
                                    onClick={() => { onNavigate('SETTINGS'); setIsUserOpen(false); }}
                                    className="w-full text-left flex items-center gap-2 px-3 py-2 text-sm text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg transition-colors"
                                >
                                    <Settings size={16} /> Profile Settings
                                </button>
                                <button 
                                    onClick={() => { onNavigate('TEAMS'); setIsUserOpen(false); }}
                                    className="w-full text-left flex items-center gap-2 px-3 py-2 text-sm text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg transition-colors"
                                >
                                    <User size={16} /> My Team
                                </button>
                            </div>
                            <div className="border-t border-gray-100 p-1">
                                <button 
                                    onClick={onLogout}
                                    className="w-full text-left flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <LogOut size={16} /> Sign Out
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </header>
    );
};

import React, { useState, useEffect } from 'react';
