type WidgetId = 'financials' | 'revenue' | 'map' | 'leaderboard' | 'recentDeals' | 'tasks' | 'goals';

const DEFAULT_WIDGETS: Record<WidgetId, boolean> = {
    financials: true,
    revenue: true,
    map: true,
    leaderboard: true,
    recentDeals: true,
    tasks: false,
    goals: false
};

interface DashboardProps {
    userName?: string;
}

const Dashboard: React.FC<DashboardProps> = ({ userName }) => {
    // --- State ---
    const [visibleWidgets, setVisibleWidgets] = useState<Record<WidgetId, boolean>>(() => {
        try {
            const saved = localStorage.getItem('arise_dashboard_layout');
            return saved ? JSON.parse(saved) : DEFAULT_WIDGETS;
        } catch { return DEFAULT_WIDGETS; }
    });

    const [isCustomizeOpen, setIsCustomizeOpen] = useState(false);
    const [isAddWidgetOpen, setIsAddWidgetOpen] = useState(false);

    // Derived Calculations
    const submittedBusiness = 245000; 
    const totalComm = 18200; 
    const upfront = totalComm * 0.75;
    const deferred = totalComm * 0.25;

    // --- Handlers ---
    useEffect(() => {
        localStorage.setItem('arise_dashboard_layout', JSON.stringify(visibleWidgets));
    }, [visibleWidgets]);

    const toggleWidget = (id: WidgetId) => {
        setVisibleWidgets(prev => ({ ...prev, [id]: !prev[id] }));
    };

    const handleAddWidget = (id: WidgetId) => {
        setVisibleWidgets(prev => ({ ...prev, [id]: true }));
        setIsAddWidgetOpen(false);
    };

    // --- Render ---
    return (
        <div className="space-y-6 animate-fade-in pb-10 relative">

            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Hello, {userName || 'Agent'}!</h2>
                    <p className="text-slate-500 text-sm mt-1">Here is a snapshot of your performance today.</p>
                </div>
                <div className="flex gap-2">
                    <button 
                        onClick={() => setIsCustomizeOpen(true)}
                        className="text-xs font-bold bg-white border border-gray-200 text-slate-600 px-4 py-2 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2"
                    >
                        <Settings size={14} /> Customize Layout
                    </button>
                    <button 
                        onClick={() => setIsAddWidgetOpen(true)}
                        className="text-xs font-bold bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-sm flex items-center gap-2"
                    >
                        <Plus size={14} /> Add Widget
                    </button>
                </div>
            </div>

            {/* Detailed Financial Cards (Top Row) */}
            {visibleWidgets.financials && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-fade-in">
                    <FinancialCard 
                        title="Submitted Business" 
                        value={`$${submittedBusiness.toLocaleString()}`} 
                        subtext="Total Volume" 
                        iconColor="text-blue-600" 
                        trend="+12%"
                    />
                    <FinancialCard 
                        title="Total Commission" 
                        value={`$${totalComm.toLocaleString()}`} 
                        subtext="Projected Income" 
                        iconColor="text-indigo-600"
                        trend="+8%" 
                    />
                    <FinancialCard 
                        title="Upfront Commission" 
                        value={`$${upfront.toLocaleString()}`} 
                        subtext="75% Advance" 
                        iconColor="text-emerald-600" 
                    />
                    <FinancialCard 
                        title="Deferred Commission" 
                        value={`$${deferred.toLocaleString()}`} 
                        subtext="Backend & Renewals" 
                        iconColor="text-purple-600" 
                    />
                </div>
            )}

            {/* Main Content Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Center / Left Column (Charts) */}
                <div className="lg:col-span-2 space-y-6">
                    {visibleWidgets.revenue && (
                        <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm animate-fade-in">
                            <div className="flex justify-between items-center mb-6">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800">Revenue Overview</h3>
                                    <p className="text-xs text-slate-500">Track your sales progress.</p>
                                </div>
                                <select className="bg-gray-50 border border-gray-200 text-xs rounded-lg px-2 py-1 outline-none text-slate-600 font-medium">
                                    <option>This Month</option>
                                    <option>Last Quarter</option>
                                    <option>YTD</option>
                                </select>
                            </div>
                            <div className="h-80 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <AreaChart data={revenueData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                                        <defs>
                                            <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(value) => `$${value/1000}k`} />
                                        <Tooltip 
                                            contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} 
                                            formatter={(value: number) => [`$${value.toLocaleString()}`, 'Revenue']}
                                        />
                                        <Area type="monotone" dataKey="revenue" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
                                    </AreaChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    )}

                    {visibleWidgets.map && (
                        <div className="bg-slate-900 rounded-xl shadow-sm p-6 text-white relative overflow-hidden flex flex-col justify-center min-h-[200px] animate-fade-in">
                            <div className="relative z-10">
                                <h3 className="font-bold text-lg mb-2">US Policy Map</h3>
                                <p className="text-slate-300 text-sm max-w-md">
                                    Geographic distribution of your active book. (Map visualization coming soon).
                                </p>
                            </div>
                            <div className="absolute right-0 top-0 bottom-0 w-1/3 bg-gradient-to-l from-indigo-600/20 to-transparent"></div>
                        </div>
                    )}
                </div>

                {/* Right Sidebar (Widgets) */}
                <div className="space-y-6 flex flex-col">
                    {visibleWidgets.leaderboard && <MiniLeaderboard />}
                    {visibleWidgets.tasks && <TaskSnapshot />}
                    {visibleWidgets.goals && <GoalWidget />}
                    {visibleWidgets.recentDeals && <RecentDeals />}
                </div>
            </div>

            {/* --- CUSTOMIZE MODAL --- */}
            {isCustomizeOpen && (
                <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
                        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <Layout size={18} className="text-indigo-600" /> Dashboard Layout
                            </h3>
                            <button onClick={() => setIsCustomizeOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X size={20} />
                            </button>
                        </div>
                        <div className="p-4 space-y-1">
                            {Object.keys(DEFAULT_WIDGETS).map((key) => {
                                const id = key as WidgetId;
                                const isVisible = visibleWidgets[id];
                                let label = '';
                                switch(id) {
                                    case 'financials': label = 'Financial Cards'; break;
                                    case 'revenue': label = 'Revenue Chart'; break;
                                    case 'map': label = 'Policy Map'; break;
                                    case 'leaderboard': label = 'Mini Leaderboard'; break;
                                    case 'recentDeals': label = 'Recent Deals'; break;
                                    case 'tasks': label = 'Tasks Snapshot'; break;
                                    case 'goals': label = 'Goal Progress'; break;
                                }

                                return (
                                    <div 
                                        key={id}
                                        onClick={() => toggleWidget(id)}
                                        className="flex items-center justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer transition-colors"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className={`w-8 h-8 rounded-full flex items-center justify-center ${isVisible ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                                                {isVisible ? <Eye size={16} /> : <EyeOff size={16} />}
                                            </div>
                                            <span className={`text-sm font-medium ${isVisible ? 'text-slate-800' : 'text-slate-400'}`}>{label}</span>
                                        </div>
                                        <div className={`w-10 h-5 rounded-full relative transition-colors ${isVisible ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                                            <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${isVisible ? 'left-6' : 'left-1'}`}></div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                        <div className="p-4 border-t border-gray-100 bg-gray-50 flex justify-end">
                            <button 
                                onClick={() => setIsCustomizeOpen(false)}
                                className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-bold hover:bg-indigo-700 transition-colors shadow-sm"
                            >
                                Done
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- ADD WIDGET MODAL --- */}
            {isAddWidgetOpen && (
                <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden">
                        <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <Plus size={20} className="text-indigo-600" /> Add Widget
                            </h3>
                            <button onClick={() => setIsAddWidgetOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X size={20} />
                            </button>
                        </div>
                        <div className="p-6">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {/* Task Widget */}
                                <button 
                                    onClick={() => handleAddWidget('tasks')}
                                    disabled={visibleWidgets.tasks}
                                    className={`p-4 rounded-xl border text-left transition-all ${visibleWidgets.tasks ? 'border-gray-200 bg-gray-50 opacity-60 cursor-default' : 'border-gray-200 hover:border-indigo-500 hover:shadow-md bg-white'}`}
                                >
                                    <div className="w-10 h-10 bg-green-50 text-green-600 rounded-lg flex items-center justify-center mb-3">
                                        <CheckSquare size={20} />
                                    </div>
                                    <h4 className="font-bold text-slate-800 text-sm">Task Snapshot</h4>
                                    <p className="text-xs text-slate-500 mt-1">View your top 3 pending tasks.</p>
                                    {visibleWidgets.tasks && <span className="text-[10px] font-bold text-green-600 flex items-center gap-1 mt-2"><CheckCircle2 size={10} /> Added</span>}
                                </button>

                                {/* Goal Widget */}
                                <button 
                                    onClick={() => handleAddWidget('goals')}
                                    disabled={visibleWidgets.goals}
                                    className={`p-4 rounded-xl border text-left transition-all ${visibleWidgets.goals ? 'border-gray-200 bg-gray-50 opacity-60 cursor-default' : 'border-gray-200 hover:border-indigo-500 hover:shadow-md bg-white'}`}
                                >
                                    <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-lg flex items-center justify-center mb-3">
                                        <Target size={20} />
                                    </div>
                                    <h4 className="font-bold text-slate-800 text-sm">Goal Progress</h4>
                                    <p className="text-xs text-slate-500 mt-1">Track your primary premium goal.</p>
                                    {visibleWidgets.goals && <span className="text-[10px] font-bold text-green-600 flex items-center gap-1 mt-2"><CheckCircle2 size={10} /> Added</span>}
                                </button>

                                {/* Placeholder Widgets */}
                                <div className="p-4 rounded-xl border border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed">
                                    <div className="w-10 h-10 bg-slate-200 text-slate-400 rounded-lg flex items-center justify-center mb-3">
                                        <DollarSign size={20} />
                                    </div>
                                    <h4 className="font-bold text-slate-500 text-sm">Cash Flow</h4>
                                    <p className="text-xs text-slate-400 mt-1">Coming Soon</p>
                                </div>
                                <div className="p-4 rounded-xl border border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed">
                                    <div className="w-10 h-10 bg-slate-200 text-slate-400 rounded-lg flex items-center justify-center mb-3">
