        .flatMap(client => client.policies.map(policy => ({ ...policy, clientName: `${client.firstName} ${client.lastName}`, clientAvatar: client.avatarUrl })))
        .filter(p => p.status === 'Active' || p.status === 'Approved')
        .slice(0, 5); 

    return (
        <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden h-full flex flex-col">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50 shrink-0">
                <h3 className="font-bold text-slate-800 text-sm">Recent Deals</h3>
                <MoreHorizontal size={16} className="text-gray-400 cursor-pointer hover:text-slate-600" />
            </div>
            <div className="divide-y divide-gray-50 flex-1 overflow-y-auto custom-scrollbar">
                {recentDeals.length > 0 ? recentDeals.map((deal) => (
                    <div key={deal.id} className="p-3 flex items-center justify-between hover:bg-slate-50 transition-colors group cursor-pointer">
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold text-xs shrink-0">
                                {deal.clientName.charAt(0)}
                            </div>
                            <div className="min-w-0">
                                <p className="text-xs font-bold text-slate-700 truncate">{deal.clientName}</p>
                                <p className="text-[10px] text-slate-400 truncate">{deal.carrier} • {deal.productName || deal.type}</p>
                            </div>
                        </div>
                        <div className="text-right shrink-0">
                            <p className="text-xs font-bold text-green-600">+${deal.premium.toLocaleString()}</p>
                            <p className="text-[10px] text-gray-400">{new Date(deal.startDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</p>
                        </div>
                    </div>
                )) : (
                    <div className="p-6 text-center text-xs text-gray-400">No recent deals found.</div>
                )}
